NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Matthew'

CHAPTERS = {
    1: {
        1: 'Das Buch von der Geburt Jesu Christi, des Sohnes Davids, des Sohnes Abrahams.',
        2: 'Abraham zeugte Isaak. Isaak aber zeugte Jakob. Jakob aber zeugte Judas und seine Brüder.',
        3: 'Judas aber zeugte Phares und Zara von der Thamar. Phares aber zeugte Esrom. Esrom aber zeugte Aram.',
        4: 'Aram aber zeugte Aminadab. Aminadab aber zeugte Naasson, Naasson aber zeugte Salmon.',
        5: 'Salmon aber zeugte Boas von der Rachab. Boas aber zeugte Obed von der Ruth, Obed aber zeugte den Jesse.',
        6: 'Jesse aber zeugte den König David. Aber der König David zeugte Salomoh von dem Weibe des Uriah.',
        7: 'Salomoh aber zeugte Roboam. Roboam aber zeugte Abia. Abia aber zeugte Asa.',
        8: 'Asa aber zeugte Josaphat. Josaphat aber zeugte Joram. Joram aber zeugte Osiah.',
        9: 'Osiah aber zeugte Joatham. Joatham aber zeugte Achas. Achas aber zeugte Ezechias.',
        10: 'Ezechias aber zeugte Manasseh. Manasseh aber zeugte Amon. Amon aber zeugte Josias.',
        11: 'Josias aber zeugte Jechonjas und seine Brüder zur Zeit der Umsiedelung nach Babylon.',
        12: 'Nach der Umsiedelung nach Babylon aber zeugte Jechonjas den Salathiel, Salathiel aber zeugte Zorobabel.',
        13: 'Zorobabel aber zeugte Abiud. Abiud aber zeugte Eliakim. Eliakim aber zeugte Azor.',
        14: 'Azor aber zeugte Zadok. Zadok aber zeugte Achim. Achim aber zeugte Eliud.',
        15: 'Eliud aber zeugte Eleasar. Eleasar aber zeugte Matthan. Matthan aber zeugte Jakob.',
        16: 'Jakob aber zeugte Joseph, den Mann der Maria, von welcher Jesus, Der da heißt Christus, geboren ward.',
        17: 'Alle die Geschlechter nun von Abraham bis David sind vierzehn Geschlechter; und von David bis zur Umsiedelung nach Babylon vierzehn Geschlechter; und von der Umsiedelung nach Babylon bis auf Christus sind es vierzehn Geschlechter.',
        18: 'Die Geburt Jesu Christi aber war also. Als nämlich Maria, Seine Mutter, dem Joseph verlobt war, fand sich, ehe sie zusammen kamen, daß sie vom Heiligen Geist empfangen hatte.',
        19: 'Joseph aber, ihr Mann, da er gerecht war, und sie nicht beschimpfen wollte, war willens, sie insgeheim zu entlassen.',
        20: 'Während er aber also gedachte, siehe, da erschien ihm der Engel des Herrn im Traum und sprach: Joseph, Sohn Davids, fürchte dich nicht, Maria, dein Weib zu dir zu nehmen; denn das in ihr Gezeugte ist von dem Heiligen Geist.',
        21: 'Sie aber wird einen Sohn gebären, und Seinen Namen sollst du Jesus heißen; denn Er wird Sein Volk von seinen Sünden retten.',
        22: 'Dies alles ist aber geschehen, auf daß erfüllt würde, was vom Herrn durch den Propheten gesprochen worden, welcher sagt:',
        23: 'Siehe, die Jungfrau wird empfangen und einen Sohn gebären; und sie sollen Seinen Namen heißen Emmanuel, welches ist verdolmetscht: Gott mit uns.',
        24: 'Vom Schlafe erwacht aber tat Joseph, wie ihm der Engel des Herrn verordnet hatte, und nahm sein Weib zu sich;',
        25: 'Und er erkannte sie nicht bis sie ihren erstgeborenen Sohn geboren hatte, und hieß Seinen Namen Jesus.',
    },
    2: {
        1: 'Als aber Jesus zu Bethlehem in Judäa geboren ward in den Tagen des Königs Herodes, siehe, da kamen Weise aus dem Morgenland nach Jerusalem, und sagten:',
        2: 'Wo ist der zum König der Juden Geborene? Denn wir haben seinen Stern gesehen im Morgenlande und sind gekommen, ihn anzubeten.',
        3: 'Da aber der König Herodes das hörte, erbebte er und ganz Jerusalem mit ihm.',
        4: 'Und er versammelte alle Hohepriester und Schriftgelehrte des Volkes und erfragte von ihnen, wo der Christus sollte geboren werden.',
        5: 'Sie aber sagten ihm: Zu Bethlehem in Judäa; denn also ist geschrieben durch den Propheten:',
        6: 'Und du, Bethlehem, im Lande Juda, bist mitnichten die kleinste unter den Fürsten Judas; denn aus dir wird ausgehen der Fürst, der Mein Volk Israel weiden wird.',
        7: 'Da ließ Herodes die Weisen insgeheim rufen und erkundete von ihnen genau die Zeit, da der Stern erschien;',
        8: 'Und schickte sie nach Bethlehem und sprach: Ziehet hin und erforschet genau wegen dem Kindlein, wenn ihr es aber gefunden habt, so saget es mir an, daß auch ich komme und es anbete.',
        9: 'Als sie aber den König gehört hatten, zogen sie hin; und siehe, der Stern, den sie im Morgenland gesehen, ging vor ihnen her, bis er kam und stand oben über der Stelle, da das Kindlein war.',
        10: 'Da sie aber den Stern sahen, freuten sie sich mit sehr großer Freude.',
        11: 'Und sie gingen in das Haus und fanden das Kindlein mit Seiner Mutter Maria, und fielen nieder und beteten Es an und taten ihre Schätze auf und brachten Ihm Gaben dar, Gold und Weihrauch und Myrrhen.',
        12: 'Und da sie im Traume angewiesen wurden, sich nicht wieder zu Herodes zu wenden, zogen sie auf einem anderen Wege in ihr Land zurück.',
        13: 'Nachdem sie aber fortgezogen waren, siehe, da erscheint der Engel des Herrn dem Joseph im Traum und sagt: Mache dich auf, nimm das Kindlein und Seine Mutter zu dir und fliehe nach Ägypten und sei dort, bis Ich es dir sage: denn Herodes wird nach dem Kindlein suchen, um Es umzubringen.',
        14: 'Er aber machte sich auf, nahm das Kindlein und Seine Mutter zu sich bei Nacht und entwich nach Ägypten;',
        15: 'Und er war da bis zum Tode des Herodes, auf daß erfüllt würde, was vom Herrn gesprochen wurde durch den Propheten, der da sagt: Aus Ägypten habe Ich Meinen Sohn gerufen.',
        16: 'Da Herodes sah, daß er von den Weisen verspottet war, ward er gar sehr ergrimmt, sandte aus und ließ in Bethlehem und an allen seinen Grenzen alle Kinder von zwei Jahren und darunter umbringen, nach der Zeit, die er von den Weisen genau erkundet hatte.',
        17: 'Da ward erfüllt, das da gesagt ist durch den Propheten Jeremias, welcher sagt:',
        18: 'In Rama ward eine Stimme gehört: Viel Klagen und Weinen und Jammern: Rachel weinte um ihre Kinder und wollte sich nicht trösten lassen, denn sie sind nicht mehr.',
        19: 'Als aber Herodes gestorben war, siehe, da erscheint der Engel des Herrn dem Joseph im Traum in Ägypten,',
        20: 'Und spricht: Mache dich auf, nimm das Kindlein und Seine Mutter zu dir und ziehe hin in das Land Israel, denn sie sind gestorben, die dem Kinde nach dem Leben trachteten.',
        21: 'Er aber machte sich auf, nahm das Kindlein und Seine Mutter zu sich und ging in das Land Israel.',
        22: 'Wie er aber hörte, daß Archelaus anstatt seines Vaters Herodes König über Judäa sei, fürchtete er sich, dahin zu gehen; aber da er im Traum angewiesen ward, zog er in die Gegend von Galiläa.',
        23: 'Und er kam dahin und wohnte in der Stadt genannt Nazareth, auf daß erfüllt würde, was durch die Propheten gesagt worden ist: Er soll ein Nazarener heißen.',
    },
    3: {
        1: 'In jenen Tagen aber trat Johannes der Täufer auf und predigte in der Wüste Judäas.',
        2: 'Und sprach: Tut Buße, denn das Reich der Himmel hat sich genaht.',
        3: 'Denn er ist es, von dem der Prophet Jesajas gesagt hat und gesprochen: Die Stimme eines, der schreit in der Wüste: Bereitet den Weg des Herrn und machet Seine Steige gerade.',
        4: 'Er aber, Johannes, hatte eine Kleidung von Kamelhaaren und einen ledernen Gürtel um seine Lenden; seine Nahrung aber war Heuschrecken und wilder Honig.',
        5: 'Da zog denn Jerusalem und ganz Judäa und die ganze Umgegend des Jordan zu ihm hinaus.',
        6: 'Und wurden von ihm im Jordan getauft, und bekannten ihre Sünden.',
        7: 'Da er aber viele der Pharisäer und Sadduzäer zu seiner Taufe kommen sah, sprach er zu ihnen: Ihr Otterngezüchte, wer hat euch denn gewiesen, vor dem zukünftigen Zorne zu fliehen?',
        8: 'So tut den Früchte würdig der Buße.',
        9: 'Und meinet nicht, ihr dürfet in euch sagen: Wir haben Abraham zum Vater; denn ich sage euch: Gott kann Abraham aus diesen Steinen da Kinder erwecken.',
        10: 'Es liegt aber auch schon die Axt an der Wurzel der Bäume. Jeglicher Baum nun, der nicht gute Frucht trägt, wird abgehauen und ins Feuer geworfen.',
        11: 'Ich taufe euch zwar im Wasser zur Buße; Der aber nach mir kommt, ist stärker, denn ich, Dem ich nicht genugsam bin, die Schuhe zu tragen, Der wird euch mit dem Heiligen Geist und mit Feuer taufen.',
        12: 'Er hat die Wurfschaufel in Seiner Hand und wird Seine Tenne durch und durch reinigen und Seinen Weizen in die Scheune sammeln, die Spreu aber in unauslöschlichem Feuer verbrennen.',
        13: 'Alsdann kommt Jesus aus Galiläa herbei an den Jordan zu Johannes, um Sich von ihm taufen zu lassen.',
        14: 'Johannes aber wehrte Ihm und sprach: Ich bedarf, daß ich von Dir getauft werde, und Du kommst zu mir?',
        15: 'Jesus aber antwortete und sprach zu ihm: Laß es jetzt zu, denn so gebührt es uns, alle Gerechtigkeit zu erfüllen. Da ließ er es Ihm zu.',
        16: 'Und da Jesus getauft war, stieg Er alsbald herauf aus dem Wasser, und siehe, die Himmel taten sich Ihm auf, und Er sah den Geist Gottes wie eine Taube herabsteigen und auf Ihn kommen.',
        17: 'Und siehe, eine Stimme sprach aus den Himmeln: Dies ist Mein geliebter Sohn, an Dem Ich Wohlgefallen habe.',
    },
    4: {
        1: 'Da ward Jesus vom Geist in die Wüste hinaufgeführt, auf daß Er vom Teufel versucht würde.',
        2: 'Und da Er vierzig Tage und vierzig Nächte gefastet hatte, hungerte Ihn danach.',
        3: 'Und der Versucher kam herzu und sprach zu Ihm: Wenn Du Gottes Sohn bist, so sprich, daß diese Steine sollen Brot werden.',
        4: 'Er aber antwortete und sprach: Es ist geschrieben: Der Mensch soll nicht allein vom Brote leben, sondern von jeglichem Wort, das durch den Mund Gottes ausgeht.',
        5: 'Da nimmt Ihn der Teufel mit sich in die heilige Stadt und stellt Ihn auf die Zinne des Tempels,',
        6: 'Und spricht zu Ihm: Wenn Du Gottes Sohn bist, so wirf Dich hinab; denn es ist geschrieben, daß Er Seinen Engeln gebieten wird ob Dir, und sie sollen Dich auf den Händen tragen, auf daß Du Deinen Fuß nicht an einen Stein stoßest.',
        7: 'Sprach zu ihm Jesus: Wiederum ist geschrieben: du sollst den Herrn, deinen Gott, nicht versuchen.',
        8: 'Wiederum nimmt Ihn der Teufel mit sich auf einen ungemein hohen Berg und zeigt Ihm alle Reiche der Welt und ihre Herrlichkeit,',
        9: 'Und spricht zu Ihm: Dies alles will ich Dir geben, wenn Du niederfällst und mich anbetest.',
        10: "Da spricht zu ihm Jesus: Geh' hinweg hinter Mich, Satan, denn es ist geschrieben: Du sollst den Herrn, deinen Gott, anbeten und Ihm allein dienen.",
        11: 'Da verläßt Ihn der Teufel, und siehe, Engel kamen herzu und bedienten Ihn.',
        12: 'Als Er aber hörte, daß Johannes überantwortet ward, zog Er hin nach Galiläa.',
        13: 'Und Er verließ Nazareth, kam und wohnte in Kapernaum, das am Meere ist, in den Grenzen Sebulons und Nephthalims.',
        14: 'Auf daß erfüllt würde, was gesagt wird durch den Propheten Jesajas, der da spricht:',
        15: 'Das Land Sebulon und das Land Nephthalim am Wege des Meeres jenseits des Jordan und Galiläa der Völkerschaften.',
        16: 'Das Volk, das im Finstern saß, hat ein großes Licht gesehen, und denen, die in der Landschaft und dem Schatten des Todes saßen, ist ein Licht aufgegangen.',
        17: 'Von da an fing Jesus an zu predigen und zu sprechen: Tut Buße, denn das Reich der Himmel hat sich genaht.',
        18: 'Wie Jesus aber an dem Meere Galiläas wandelte, sah er zwei Brüder, Simon, genannt Petrus, und seinen Bruder Andreas, wie sie ein Fischnetz in das Meer warfen; denn sie waren Fischer.',
        19: 'Und Er spricht zu ihnen: Kommet her, Mir nach, und Ich will euch zu Menschenfischern machen.',
        20: 'Sie aber verließen alsbald die Netze und folgten Ihm nach.',
        21: 'Und Er ging von dannen weiter und sah zwei andere Brüder, Jakobus, den des Zebedäus, und Johannes, seinen Bruder, in dem Fahrzeug mit Zebedäus, ihrem Vater, wie sie ihre Netze zurichteten, und Er rief sie.',
        22: 'Sie aber verließen alsbald das Fahrzeug und ihren Vater und folgten Ihm nach.',
        23: 'Und Jesus zog umher in ganz Galiläa, lehrte in ihren Synagogen und predigte das Evangelium von dem Reiche und heilte alle Krankheit und alles Siechtum im Volke.',
        24: 'Und Sein Gerücht ging hin in ganz Syrien, und sie brachten Ihm alle Leidende, die mit mancherlei Krankheiten und Qualen behaftet waren, und Besessene und Mondsüchtige und Gichtbrüchige, und Er heilte sie.',
        25: 'Und es folge Ihm nach viel Volks von Galiläa und den zehn Städten, und von Jerusalem und von Judäa, und von jenseits des Jordan.',
    },
    5: {
        1: 'Als Er aber das Gedränge sah, stieg Er auf den Berg, und als Er Sich niedersetzte, kamen Seine Jünger herzu zu Ihm.',
        2: 'Und Er tat Seinen Mund auf, lehrte sie und sprach:',
        3: 'Selig sind, die im Geiste arm sind, denn das Reich der Himmel ist ihr.',
        4: 'Selig sind, die da Leid tragen, denn sie sollen getröstet werden.',
        5: 'Selig sind die Sanftmütigen, denn sie werden das Land ererben.',
        6: 'Selig sind, die da hungert und dürstet nach Gerechtigkeit, denn sie sollen satt werden.',
        7: 'Selig sind die Barmherzigen, denn sie werden Barmherzigkeit erlangen.',
        8: 'Selig sind, die reinen Herzens sind, denn sie werden Gott schauen.',
        9: 'Selig sind die Friedensstifter, denn sie werden Gottes Söhne heißen.',
        10: 'Selig sind, die um Gerechtigkeit willen verfolgt werden, denn das Reich der Himmel ist ihr.',
        11: 'Selig seid ihr, wenn sie euch schelten und verfolgen und reden allerlei Übles wider euch um Meinetwillen, so sie daran lügen.',
        12: 'Freuet euch und frohlocket, denn viel ist eures Lohns in den Himmeln; denn also verfolgten sie die Propheten, die vor euch gewesen.',
        13: 'Ihr seid das Salz der Erde; so aber das Salz fade wird, womit soll man salzen? Es ist zu nichts mehr nütze, als daß man es hinausirft, und es von den Menschen niedergetreten wird.',
        14: 'Ihr seid das Licht der Welt. Eine Stadt, die auf dem Berge liegt, kann nicht verborgen sein.',
        15: 'Noch zündet man eine Kerze an und setzt sie unter einen Scheffel, sondern auf einen Leuchter, und sie leuchtet allen, die im Hause sind.',
        16: 'Also lasset euer Licht leuchten vor den Menschen, daß sie eure guten Werke sehen und euren Vater in den Himmeln verherrlichen.',
        17: 'Denket nicht, daß Ich gekommen sei, das Gesetz oder die Propheten aufzulösen; Ich bin nicht gekommen aufzulösen, sondern zu erfüllen.',
        18: 'Denn wahrlich sage Ich euch: Bis daß Himmel und Erde vergehen, soll kein Jod noch ein Strichlein vom Gesetz vergehen, bis daß alles geschehe.',
        19: 'Wer nun eins dieser kleinsten Gebote löset, und lehret die Menschen also, wird der Kleinste heißen im Reiche der Himmel; wer aber tut und lehrt, der wird groß heißen im Reiche der Himmel.',
        20: 'Denn Ich sage euch: Es sei denn, daß eure Gerechtigkeit weit übertreffe die der Schriftgelehrten und Pharisäer, so werdet ihr nicht in das Reich der Himmel eingehen.',
        21: 'Ihr habt gehört, daß zu den Alten gesagt ist: Du sollst nicht morden; wer aber mordet, der soll dem Gericht verfallen sein.',
        22: 'Ich aber sage euch: Wer seinem Bruder zürnt, ist dem Gericht verfallen; wer aber zu seinem Bruder sagt: Raka, der verfällt dem Rat; wer aber sagt: Du Narr, der verfällt der Hölle des Feuers.',
        23: 'Wenn du denn deine Gabe auf dem Altar darbringst, und allda gedenkst, daß dein Bruder etwas wider dich hat,',
        24: 'So laß allda vor dem Altar deine Gabe und geh erst hin und versöhne dich mit deinem Bruder und dann komm und bringe deine Gabe dar.',
        25: 'Sei willfährig gegen deinen Widersacher, schnell, während du mit ihm auf dem Wege bist, auf daß dich der Widersacher nicht dem Richter überantworte und der Richter dich überantworte dem Amtsdiener und du in das Gefängnis geworfen werdest.',
        26: 'Wahrlich, Ich sage dir, du wirst nicht von dannen herauskommen, bis daß du auch den letzten Heller bezahlst.',
        27: 'Ihr habt gehört, daß zu den Alten gesagt ist: Du sollst nicht ehebrechen.',
        28: 'Ich aber sage euch, daß, wer ein Weib ansieht, um ihrer zu begehren, der hat schon mit ihr die Ehe gebrochen in seinem Herzen.',
        29: 'Ärgert dich aber dein rechtes Auge, so reiß es aus und wirf es von dir; denn es ist dir zuträglicher, daß eins deiner Glieder verderbe, denn daß dein ganzer Leib in die Hölle geworfen werde.',
        30: 'Und ärgert dich deine rechte Hand, so haue sie ab und wirf sie von dir; denn es ist dir zuträglicher, daß eins deiner Glieder verderbe, denn daß dein ganzer Leib in die Hölle geworfen werde.',
        31: 'Es ist aber gesagt worden: Wer sich von seinem Weibe scheidet, der gebe ihr einen Scheidebrief.',
        32: 'Ich aber sage euch: Wer sich von seinem Weibe scheidet, es sei denn wegen Buhlerei, der macht, daß sie die Ehe bricht; und wer eine Geschiedene freit, der bricht die Ehe.',
        33: 'Wiederum habt ihr gehört, daß zu den Alten gesagt ist: Du sollst keinen falschen Eid tun, sondern dem Herrn deinen Eid halten.',
        34: 'Ich aber sage euch: Ihr sollt gar nicht schwören, weder bei dem Himmel, denn er ist Gottes Thron;',
        35: 'Noch bei der Erde, denn sie ist Seiner Füße Schemel; noch bei Jerusalem, denn sie ist des großen Königs Stadt.',
        36: 'Auch nicht bei deinem Haupt sollst du schwören, denn du kannst nicht ein Haar weiß oder schwarz machen.',
        37: 'Euer Wort aber sei: Ja, ja, nein, nein. Was weiter ist, das ist vom Übel.',
        38: 'Ihr habt gehört, daß gesagt ist: Augâ¬Ü um Auge und Zahn um Zahn.',
        39: 'Ich aber sage euch: Ihr sollt dem Übel nicht widerstehen; sondern so dir einer einen Streich gibt auf deinen rechten Backen, dem wende den andern auch zu.',
        40: 'Dem, der mit dir rechten und dir den Rock nehmen will, dem laß auch das Oberkleid.',
        41: 'So dich einer eine Meile nötigt, gehe mit ihm zwei.',
        42: 'Gib dem, der dich bittet, und wende dich nicht ab von dem, der von dir entlehnen will.',
        43: 'Ihr habt gehört, daß gesagt ist: Du sollst deinen Nächsten lieben und deinen Feind hassen.',
        44: 'Ich aber sage euch: Liebet eure Feinde, segnet, die euch fluchen, tut wohl denen, die euch hassen, und betet für die, welche euch beleidigen und verfolgen.',
        45: 'Auf daß ihr Söhne werdet eures Vaters in den Himmeln; denn Er läßt Seine Sonne aufgehen über Schlechte und Gute, und läßt regnen über Gerechte und Ungerechte.',
        46: 'Denn so ihr liebet, die euch lieben, was für Lohn habt ihr? Tun nicht dasselbe auch die Zöllner?',
        47: 'Und wenn ihr nur eure Brüder grüßet, was tut ihr weiteres? Tun nicht die Zöllner auch also?',
        48: 'So sollt nun ihr vollkommen sein, gleichwie euer Vater in den Himmeln vollkommen ist.',
    },
    6: {
        1: 'Habt acht auf euer Almosen, daß ihr es nicht gebet vor den Menschen, um von ihnen angesehen zu werden: ihr habt anders keinen Lohn bei eurem Vater in den Himmeln.',
        2: 'Wenn du aber Almosen gibst, laß nicht vor dir her posaunen, wie die Heuchler tun in den Synagogen und in den Gassen, auf daß sie von den Leuten verherrlicht werden. Wahrlich, Ich sage euch, sie haben ihren Lohn dahin.',
        3: 'Wenn du aber Almosen gibst, laß deine linke Hand nicht wissen, was deine rechte tut;',
        4: 'Auf daß dein Almosen im Verborgenen sei, und dein Vater, Der in das Verborgene sieht, wird dir es selber vergelten öffentlich.',
        5: 'Und wenn du betest, sollst du nicht sein wie die Heuchler, die da gerne in den Synagogen und an den Ecken der Straßen stehen und beten, damit sie vor den Menschen scheinen. Wahrlich, Ich sage euch, sie haben ihren Lohn dahin.',
        6: 'Wenn du aber betest, so gehe ein in deine Kammer und verschließe deine Tür und bete zu deinem Vater im Verborgenen. Und dein Vater, Der in das Verborgene sieht, wird es dir vergelten öffentlich.',
        7: 'Wenn ihr aber betet, sollt ihr nicht plappern wie die Heiden, denn sie meinen, sie werden erhört, wenn sie viele Worte machen.',
        8: 'Seid denn ihnen nicht ähnlich; denn euer Vater weiß, was ihr bedürfet, ehe denn ihr Ihn bittet.',
        9: 'Darum sollt ihr also beten: Unser Vater in den Himmeln. Geheiligt werde Dein Name;',
        10: 'Dein Reich komme. Dein Wille geschehe, wie im Himmel, also auch auf Erden.',
        11: 'Gib uns heute unser tägliches Brot.',
        12: 'Und vergib uns unsre Schulden, wie auch wir vergeben unsern Schuldnern.',
        13: 'Und führe uns nicht in Versuchung, sondern errette uns von dem Übel; denn Dein ist das Reich und die Kraft und die Herrlichkeit in Ewigkeit. Amen.',
        14: 'Denn so ihr den Menschen ihre Fehle vergebt, so wird euch euer himmlischer Vater auch vergeben.',
        15: 'Wenn ihr aber den Menschen ihre Fehle nicht vergebet, so wird euer Vater eure Fehle auch nicht vergeben.',
        16: 'Wenn ihr aber fastet, sehet nicht düster drein, wie die Heuchler; denn sie entstellen ihre Angesichter, auf daß sie vor den Menschen scheinen mit ihrem Fasten. Wahrlich, Ich sage euch, sie haben ihren Lohn dahin.',
        17: 'Wenn du aber fastest, salbe dein Haupt und wasche dein Angesicht.',
        18: 'Auf daß du nicht vor den Menschen scheinst mit deinem Fasten, sondern vor deinem Vater im Verborgenen; und dein Vater, Der in das Verborgene sieht, wird es dir vergelten öffentlich.',
        19: 'Speichert euch nicht Schätze auf Erden, wo sie Motte und Rost fressen, und wo Diebe einbrechen und stehlen.',
        20: 'Speichert euch aber Schätze auf im Himmel, wo weder Motte noch Rost sie frißt, und wo Diebe nicht einbrechen noch stehlen.',
        21: 'Denn wo euer Schatz ist, da ist auch euer Herz.',
        22: 'Des Leibes Leuchte ist das Auge. Wenn nun dein Auge einfältig ist, so ist dein ganzer Leib licht.',
        23: 'Wenn aber dein Auge arg ist, so ist dein ganzer Leib finster. Wenn nun das Licht in dir Finsternis ist, wie groß ist die Finsternis.',
        24: 'Niemand kann zwei Herren dienen; denn entweder wird er den einen hassen und den andern lieben; oder wird er dem einen anhangen und den andern verachten. Ihr könnt nicht Gott dienen und dem Mammon.',
        25: 'Darum sage Ich euch: Sorget nicht für eure Seele, was ihr essen und was ihr trinken werdet; noch für euren Leib, was ihr antun werdet. Ist nicht die Seele mehr als die Nahrung und der Leib mehr als die Kleidung?',
        26: 'Seht das Gevögel des Himmels an, sie säen nicht, sie ernten nicht, auch sammeln sie nicht in Scheunen, und euer himmlischer Vater nähret sie doch. Seid ihr nicht mehr denn sie.',
        27: 'Wer von euch kann mit Sorgen seinem Wuchse eine Elle hinzutun?',
        28: 'Und was sorget ihr für die Kleidung? Betrachtet die Lilien des Feldes, wie sie wachsen; sie mühen sich nicht ab, auch spinnen sie nicht.',
        29: 'Ich aber sage euch: Auch Salomoh in all seiner Herrlichkeit war nicht umkleidet wie derselben eine.',
        30: 'So denn Gott das Gras des Feldes, das heute da ist und morgen in den Ofen geworfen wird, also ankleidet, um wie viel mehr euch, ihr Kleingläubigen!',
        31: 'Deshalb sollt ihr nicht sorgen und sagen: Was sollen wir essen, was sollen wir trinken, womit sollen wir uns umkleiden?',
        32: 'Nach solch allem trachten die Heiden; denn euer himmlischer Vater weiß ja, daß ihr dies alles bedürfet.',
        33: 'Trachtet am ersten nach dem Reiche Gottes und nach Seiner Gerechtigkeit; dann wird euch dies alles hinzugetan.',
        34: 'Darum sorget nicht für den morgenden Tag; denn der morgende Tag wird für das Seine sorgen. Genug für den Tag ist sein Böses.',
    },
    7: {
        1: 'Richtet nicht, auf daß ihr nicht gerichtet werdet.',
        2: 'Denn mit welcherlei Gericht ihr richtet, werdet ihr gerichtet werden, und mit welcherlei Maß ihr messet, wird euch gemessen werden.',
        3: 'Was siehst du aber den Splitter in deines Bruders Auge, den Balken aber in deinem Auge gewahrst du nicht?',
        4: 'Oder wie willst du zu deinem Bruder sagen: Laß mich, ich will dir den Splitter aus deinem Auge herausziehen? und siehe, der Balken ist in deinem Auge!',
        5: 'Du Heuchler, ziehe zuerst den Balken aus deinem Auge heraus, und dann magst du zusehen, wie du den Splitter aus deines Bruders Auge herausziehst.',
        6: 'Gebt das Heilige nicht den Hunden, und werfet eure Perlen nicht vor die Schweine, auf daß sie solche nicht mit ihren Füßen niedertreten und sich umwenden und euch zerreißen.',
        7: 'Bittet, und euch wird gegeben. Suchet, und ihr werdet finden. Klopfet an, und euch wird aufgetan.',
        8: 'Denn wer da bittet, der empfängt, und wer da sucht, der findet, und wer da anklopft, dem wird aufgetan.',
        9: 'Oder welcher Mensch ist unter euch, der, so ihn sein Sohn um Brot bäte, ihm einen Stein gäbe?',
        10: 'Oder der, wenn er ihn um einen Fisch bäte, ihm eine Schlange gäbe?',
        11: 'So denn ihr, die ihr arg seid, euren Kindern gute Gaben zu geben wisset, wie viel mehr wird euer Vater in den Himmeln Gutes geben denen, die Ihn bitten?',
        12: 'Alles nun, das ihr wollet, daß euch die Menschen tun sollen, das tuet auch ihr ihnen, denn das ist das Gesetz und die Propheten.',
        13: 'Gehet ein durch das enge Tor; denn das Tor ist weit und der Weg ist breit, der ins Verderben hinführt, und wenige sind ihrer, die ihn durch eingehen.',
        14: 'Eng aber ist das Tor und schmal der Weg, der zum Leben hinführt, und wenige sind ihrer, die ihn finden.',
        15: 'Nehmt euch in acht vor den falschen Propheten, die in Schafskleidern zu euch kommen, inwendig aber sind sie reißende Wölfe.',
        16: 'An ihren Früchten sollt ihr sie erkennen. Liest man auch Trauben von Dornen, oder Feigen von Disteln?',
        17: 'Also bringt jeglicher gute Baum gute Früchte; der faule Baum aber bringt schlechte Früchte.',
        18: 'Ein guter Baum kann nicht schlechte Früchte bringen, und ein fauler Baum kann nicht gute Früchte bringen.',
        19: 'Jeglicher Baum, der nicht gute Frucht bringt, wird abgehauen und ins Feuer geworfen.',
        20: 'Darum an ihren Früchten sollt ihr sie erkennen.',
        21: 'Es wird nicht jeder, der zu Mir sagt: Herr, Herr, ins Reich der Himmel eingehen; sondern der den Willen tut Meines Vaters in den Himmeln.',
        22: 'Viele werden zu Mir an jenem Tage sagen: Herr, Herr, haben wir nicht in Deinem Namen geweissagt? und in Deinem Namen Dämonen ausgetrieben, und haben wir nicht in Deinem Namen viele Wundertaten getan?',
        23: 'Und dann werde Ich ihnen bekennen: Ich habe euch nie erkannt. Weichet von Mir, die ihr Unrecht wirket.',
        24: 'Jeden nun, der diese Meine Worte hört und tut sie, will Ich einem klugen Manne vergleichen, der sein Haus auf den Felsen baute.',
        25: 'Und der Platzregen kam herab, und die Ströme kamen und die Winde wehten und stießen wider das Haus, und es fiel nicht; denn es war auf den Felsen gegründet.',
        26: 'Und jeder, der diese Meine Worte hört und tut sie nicht, ist einem törichten Manne zu vergleichen, der sein Haus auf den Sand baute.',
        27: 'Und der Platzregen kam herab und die Ströme kamen und die Winde wehten und stießen gegen das Haus, und es fiel, und sein Fall war groß.',
        28: 'Und es geschah, da Jesus diese Worte vollendet hatte, staunte das Volk über Seine Lehre;',
        29: 'Denn Er lehrte sie wie einer, der Gewalt hat, und nicht wie die Schriftgelehrten.',
    },
    8: {
        1: 'Da Er aber vom Berge herabstieg, folgte Ihm viel Volks nach.',
        2: 'Und siehe, ein Aussätziger kam und betete Ihn an und sprach: Herr, so Du willst, kannst Du mich reinigen.',
        3: 'Und Jesus streckte Seine Hand aus, berührte ihn und sprach: Ich will; sei gereinigt! Und alsbald war sein Aussatz gereinigt.',
        4: 'Und Jesus spricht zu ihm: Siehe, sage es niemand, sondern gehe hin, zeige dich dem Priester, und bringe die Gabe dar, die Moses verordnet hat, zum Zeugnis für sie.',
        5: 'Als Jesus aber einging nach Kapernaum, kam zu Ihm ein Hauptmann, flehte Ihn an,',
        6: 'Und sagte: Herr, mein Knabe liegt im Hause gichtbrüchig danieder, schrecklich gequält.',
        7: 'Und Jesus spricht zu ihm: Ich will kommen und ihn heilen.',
        8: 'Und der Hauptmann antwortete und sprach: Herr, ich bin nicht genugsam, daß Du unter mein Dach eingehst; sondern sprich nur ein Wort, so wird mein Knabe gesund.',
        9: 'Denn auch ich bin ein Mensch unter Obergewalt, und habe Kriegsknechte unter mir, und wenn ich zu einem sage: ziehe hin! so zieht er hin, und zum andern: komm! so kommt er, und zu meinem Knechte: tue das! so tut er es.',
        10: 'Da aber Jesus dies hörte, verwunderte Er Sich und sprach zu denen, die Ihm nachfolgten: Wahrlich, Ich sage euch: Auch nicht in Israel habe Ich solchen Glauben gefunden.',
        11: 'Aber Ich sage euch: Viele werden kommen vom Aufgang und vom Niedergang und mit Abraham und Isaak und Jakob sich niederlegen im Reiche der Himmel.',
        12: 'Die Söhne des Reichs aber werden hinausgeworfen in die äußerste Finsternis. Dort wird sein Heulen und Zähneknirschen.',
        13: 'Und Jesus sprach zu dem Hauptmann: Gehe hin, und wie du geglaubt hast, soll dir werden. Und der Knabe ward gesund zur selbigen Stunde.',
        14: 'Und als Jesus in des Petrus Haus kam, sah Er seine Schwieger liegen, und sie hatte Fieber.',
        15: 'Und Er berührte ihre Hand, und das Fieber verließ sie, und sie machte sich auf und bediente sie.',
        16: 'Als es aber Abend war, brachten sie viele Besessene zu Ihm, und Er trieb die Geister aus mit einem Wort, und Er heilte alle Leidenden;',
        17: 'Auf daß erfüllt würde, was durch den Propheten Jesajas gesagt ward, der spricht: Er hat unsere Gebrechen auf Sich genommen und unsere Krankheiten getragen.',
        18: 'Als Jesus aber das viele Gedränge um Sich sah, befahl Er, jenseits hinüber zu fahren.',
        19: 'Und es kam einer, ein Schriftgelehrter, und sprach zu Ihm: Lehrer, ich will Dir nachfolgen, wo Du auch hingehst.',
        20: 'Und Jesus spricht zu ihm: Die Füchse haben Baue, und das Gevögel des Himmels Nester; des Menschen Sohn aber hat nicht, wo Er Sein Haupt hinlege.',
        21: 'Ein anderer von Seinen Jüngern aber sprach zu Ihm: Herr, gestatte mir, daß ich zuerst hingehe und meinen Vater begrabe.',
        22: 'Jesus aber sprach zu ihm: Folge du Mir nach und lasse die Toten ihre Toten begraben.',
        23: 'Und als Er in das Fahrzeug einstieg, folgten Ihm Seine Jünger nach.',
        24: 'Und siehe, es erhob sich ein großes Ungestüm in dem Meere also, daß das Fahrzeug von den Wellen bedeckt ward. Er aber schlief.',
        25: 'Und die Jünger kamen hinzu, weckten Ihn auf und sagten: Herr, rette uns, wir verderben.',
        26: 'Und Er spricht zu ihnen: Was seid ihr furchtsam, ihr Kleingläubigen? Dann stand Er auf, bedrohte die Winde und das Meer, und es ward eine große Windstille.',
        27: 'Die Menschen aber verwunderten sich und sagten: Welcher Art ist Der, daß Ihm Winde und Meer gehorchen?',
        28: 'Und als Er hinüberkam in die Landschaft der Gardarener, kamen Ihm zwei Besessene entgegen, die aus den Grüften herauskamen, und ungemein unbändig waren, so daß niemand vermochte jenes Weges vorbeizugehen.',
        29: 'Und siehe da, sie schrien und sagten: Was haben wir mit Dir, Jesus, Du Sohn Gottes? Bist Du hierher gekommen, uns vor der Zeit zu quälen?',
        30: 'Es war aber ferne von ihnen ein Trieb vieler Schweine auf der Weide.',
        31: 'Die Dämonen aber flehten Ihn an und sagten: Wenn Du uns austreibst, so gestatte uns, in den Trieb der Schweine hinzufahren.',
        32: 'Und Er sprach zu ihnen: Fahret hin! Da kamen sie heraus und fuhren in den Trieb der Schweine. Und siehe da, der ganze Trieb von Schweinen stürzte sich von der Anhöhe hinab in das Meer und kam um in dem Wasser.',
        33: 'Und die sie weideten, flohen und gingen hin in die Stadt und sagten an alles, und auch über die Besessenen.',
        34: 'Und siehe, da kam die ganze Stadt heraus, Jesus entgegen, und da sie Ihn sahen, flehten sie Ihn an, Er möchte von ihren Grenzen weitergehen.',
    },
    9: {
        1: 'Und Er stieg ein in das Fahrzeug, fuhr hinüber und kam in Seine eigene Stadt.',
        2: 'Und siehe, da brachten sie zu Ihm einen Gichtbrüchigen, der auf einem Bette daniederlag. Und da Jesus ihren Glauben sah, sprach er zu dem Gichtbrüchigen: Sei getrost, mein Kind, deine Sünden sind dir vergeben.',
        3: 'Und siehe, einige Schriftgelehrten sprachen bei sich: Dieser lästert Gott.',
        4: 'Und da Jesus ihre Gedanken sah, sprach Er: Warum gedenkt ihr Arges in euren Herzen?',
        5: 'Denn was ist leichter zu sagen: Die Sünden sind dir vergeben, oder zu sagen: Mache dich auf und wandle?',
        6: 'Auf daß ihr aber wisset, daß des Menschen Sohn Gewalt hat auf Erden, Sünden zu vergeben: Mache dich auf, hebe dein Bett auf und gehe hin in dein Haus.',
        7: 'Und er machte sich auf und ging hin in sein Haus.',
        8: 'Da aber das Gedränge dies sah, verwunderten sie sich und verherrlichten Gott, Der solche Gewalt den Menschen gegeben habe.',
        9: 'Und da Jesus von dannen vorüberging, sah Er einen Menschen am Zolle sitzen, Matthäus genannt, und Er sprach zu Ihm: Folge Mir nach! Und er stand auf und folgte ihm nach.',
        10: 'Und es geschah, als Er im Hause zu Tische lag, siehe, da kamen viele Zöllner und Sünder und legten sich mit Jesus und Seinen Jüngern zu Tische.',
        11: 'Wie dies die Pharisäer sahen, sprachen sie zu Seinen Jüngern: Warum ißt euer Lehrer mit den Zöllnern und Sündern?',
        12: 'Jesus aber hörte es und sprach zu ihnen: Die Starken bedürfen des Arztes nicht, sondern die Leidenden.',
        13: 'Gehet aber hin und lernet, was das ist: Ich will Barmherzigkeit und nicht Opfer; denn Ich bin nicht gekommen, Gerechte, sondern Sünder zur Buße zu rufen.',
        14: 'Da kamen des Johannes Jünger herzu zu Ihm und sagten: Warum fasten wir und die Pharisäer so viel, und Deine Jünger fasten nicht?',
        15: 'Und Jesus sprach zu ihnen: Können die Söhne des Brautgemachs trauern, solange der Bräutigam bei ihnen ist? Es werden aber Tage kommen, da der Bräutigam von ihnen hinweggenommen wird, und dann werden sie fasten.',
        16: 'Niemand setzt einen Fleck ungewalkten Tuches auf ein altes Kleid; denn sein Füllwerk nimmt von dem Kleide und der Riß wird schlimmer.',
        17: 'Auch fasset man nicht neuen Wein in alte Schläuche, sonst zerreißen die Schläuche und der Wein wird verschüttet und die Schläuche verderben; sondern man fasset neuen Wein in neue Schläuche, und beide werden miteinander erhalten.',
        18: 'Während Er solches zu ihnen redete, siehe, da kam der Obersten einer, fiel vor Ihm nieder und sagte: Meine Tochter ist eben jetzt gestorben; aber komm, lege Deine Hand auf sie, und sie wird leben.',
        19: 'Und Jesus machte Sich auf, folgte Ihm nach und Seine Jünger.',
        20: 'Und siehe, eine Weib, das zwölf Jahre den Blutfluß hatte, trat von hinten herzu und berührte den Saum Seines Kleides.',
        21: 'Denn sie sagte bei sich selbst: Wenn ich nur Sein Kleid berühre, so bin ich gerettet.',
        22: 'Jesus aber wandte Sich um und sah sie und sprach: Sei getrost, Meine Tochter, dein Glaube hat dir geholfen. Und dem Weib ward geholfen zur selbigen Stunde.',
        23: 'Und Jesus kam in das Haus des Obersten und sah die Pfeifer und das lärmende Gedränge.',
        24: 'Und Er sprach zu ihnen: Weichet, denn das Mägdlein ist nicht gestorben, sondern es schlummert. Und sie verlachten Ihn.',
        25: 'Als aber das Gedränge hinausgetrieben war, ging Er hinein, ergriff sie bei der Hand, und das Mägdlein richtete sich auf.',
        26: 'Und das Gerücht davon ging aus in dasselbige ganze Land.',
        27: 'Und da Jesus von dannen weiterging, folgten Ihm zwei Blinde nach, schrien und sprachen: Sohn Davids, erbarme Dich unser!',
        28: 'Als Er aber in das Haus kam, kamen die Blinden her zu Ihm, und Jesus spricht zu ihnen: Glaubet ihr, daß Ich solches tun kann? Sie sprachen zu Ihm: Ja, Herr.',
        29: 'Da berührte Er ihre Augen und sprach: Nach eurem Glauben geschehe euch!',
        30: 'Und ihre Augen wurden aufgetan. Und Jesus drohte ihnen und sprach: Sehet zu, daß es niemand erfahre.',
        31: 'Sie aber gingen aus und machten Ihn ruchbar in selbigem ganzen Lande.',
        32: 'Als sie aber ausgingen, siehe, da brachen sie einen Menschen zu Ihm herbei, der stumm und besessen war.',
        33: 'Und als der Dämon ausgetrieben war, redete der Stumme. Und die Menge verwunderte sich, und sie sprachen: Noch nie ist solches in Israel erschienen.',
        34: 'Die Pharisäer aber sagten: Durch den Obersten der Dämonen treibt Er die Dämonen aus.',
        35: 'Und Jesus zog in allen Städten und Flecken umher, lehrte in ihren Synagogen und predigte das Evangelium des Reichs und heilte alle Krankheit und alles Siechtum im Volk.',
        36: 'Und da Er das Gedränge sah, jammerte Ihn derselben, daß sie so verschmachtet und dahingeworfen wären, wie Schafe, die keinen Hirten haben.',
        37: 'Da spricht Er zu Seinen Jüngern: Viel ist der Ernte, aber wenige sind der Arbeiter.',
        38: 'Darum flehet zum Herrn der Ernte, daß Er Arbeiter in Seine Ernte ausschicke.',
    },
    10: {
        1: 'Und Er rief Seine zwölf Jünger zu Sich, und gab ihnen Gewalt über unreine Geister, sie auszutreiben, und alle Krankheit und alles Siechtum zu heilen.',
        2: 'Die Namen der zwölf Apostel aber sind diese: Der erste Simon, genannt Petrus, und Andreas, sein Bruder; Jakobus, des Zebedäus, und Johannes, sein Bruder.',
        3: 'Philippus und Bartholomäus, Thomas und Matthäus, der Zöllner, Jakobus, des Alphäus und Lebbäus, mit dem Zunamen Thaddäus;',
        4: 'Simon, der Kananite, und Judas Ischariot, der Ihn auch verriet.',
        5: 'Diese Zwölfe sandte Jesus aus, entbot ihnen und sprach: Gehet nicht hin auf den Weg der Heiden und in eine Stadt der Samariter gehet nicht ein.',
        6: 'Zieht vielmehr hin zu den verlorenen Schafen des Hauses Israels.',
        7: 'Wenn ihr aber hinzieht, predigt und sprechet: Das Reich der Himmel hat sich genaht.',
        8: 'Heilt die Siechen, reinigt Aussätzige, weckt Tote auf, treibt Dämonen aus. Umsonst habt ihr empfangen, umsonst gebt.',
        9: 'Ihr sollt nicht besitzen Gold noch Silber, noch Erz in euren Gürteln.',
        10: 'Keine Tasche auf den Weg, noch zwei Röcke, noch Sandalen, noch Stab; denn der Arbeiter ist seiner Nahrung wert.',
        11: 'Wo ihr aber in eine Stadt oder in einen Flecken eingeht, erforschet, wer darin ist, der es wert ist, und dort bleibt, bis ihr von dannen ausgeht.',
        12: 'So ihr aber in das Haus eingeht, grüßet dasselbe.',
        13: 'Und so das Haus es wert ist, komme euer Friede auf dasselbe. Ist es aber nicht wert, so wende sich euer Friede zurück zu euch.',
        14: 'Und so euch einer nicht aufnimmt, noch auf eure Worte hört, so geht aus jenem Hause oder jener Stadt hinaus und schüttelt den Staub eurer Füße ab.',
        15: 'Wahrlich, Ich sage euch: Es wird dem Lande der Sodomer und Gomorrer erträglicher sein am Tage des Gerichts, als jener Stadt.',
        16: 'Siehe, Ich sende euch aus wie Schafe mitten unter Wölfe. Seid denn klug, wie die Schlangen, und ohne Falsch, wie die Tauben.',
        17: 'Nehmt euch aber in acht vor den Menschen; denn sie werden euch überantworten ihren Räten und euch geißeln in ihren Synago- gen.',
        18: 'Und sie werden euch wegen Meiner vor Fürsten und Könige führen, zum Zeugnis über sie und über die Heiden.',
        19: 'Wenn sie euch aber überantworten, so sorget nicht, wie oder was ihr reden sollt; denn es wird euch zu jener Stunde gegeben werden, was ihr reden sollt.',
        20: 'Denn nicht ihr seid es, die das reden, sondern der Geist eures Vaters ist es, der in euch redet.',
        21: 'Es wird aber ein Bruder den Bruder und der Vater das Kind zum Tode überantworten; und Kinder werden gegen Eltern aufstehen und sie zum Tode bringen.',
        22: 'Und ihr werdet gehaßt werden von allen um Meines Namens willen; wer aber beharrt bis ans Ende, der wird gerettet werden.',
        23: 'Wenn sie euch aber verfolgen in einer Stadt, so flieht in die andere, denn wahrlich, Ich sage euch: Ihr werdet mit den Städten Israels nicht zu Ende sein, bis des Menschen Sohn kommen wird.',
        24: 'Der Jünger ist nicht über dem Lehrer, noch der Knecht über seinem Herrn.',
        25: 'Es ist genug für den Jünger, daß er sei wie sein Lehrer, und der Knecht wie sein Herr. Haben sie den Hausherrn Beelzebub geheißen, wieviel mehr seine Hausgenossen.',
        26: 'Darum fürchtet euch nicht vor ihnen; denn nichts ist verdeckt, das nicht offenbar würde, und nichts verborgen, das man nicht erkennen wird.',
        27: 'Was Ich euch sage in der Finsternis, das sprechet im Licht, und was ihr höret in das Ohr, das predigt auf den Dächern.',
        28: 'Und fürchtet euch nicht vor denen, die den Leib töten, die Seele aber nicht töten können. Fürchtet euch aber vielmehr vor dem, der Seele und Leib in der Hölle verderben kann.',
        29: 'Verkauft man nicht zwei Sperlinge um einen Pfennig? Und keiner derselben fällt zur Erde ohne euren Vater.',
        30: 'Es sind aber auch die Haare eures Hauptes alle gezählt.',
        31: 'Darum fürchtet euch nicht. Ihr seid mehr, denn viele Sperlinge.',
        32: 'Einen jeden, der Mich bekennt vor den Menschen, den will Ich auch bekennen vor Meinem Vater in den Himmeln.',
        33: 'Wer Mich aber verleugnet vor den Menschen, den werde Ich auch verleugnen vor Meinem Vater in den Himmeln.',
        34: 'Denket nicht, daß Ich gekommen bin, Frieden auf die Erde zu bringen. Ich bin nicht gekommen, Frieden zu bringen, sondern das Schwert.',
        35: 'Denn Ich bin gekommen, den Menschen mit seinem Vater zu entzweien und die Tochter mit ihrer Mutter, und die Schnur mit ihrer Schwieger.',
        36: 'Und die Feinde des Menschen werden seine eigenen Hausgenossen sein.',
        37: 'Wer Vater oder Mutter mehr lieb hat, denn Mich, der ist Meiner nicht wert; und wer Sohn oder Tochter mehr lieb hat, denn Mich, der ist Meiner nicht wert.',
        38: 'Und wer nicht sein Kreuz auf sich nimmt und hinter Mir nachfolgt, der ist Meiner nicht wert.',
        39: 'Wer seine Seele findet, der wird sie verlieren; und wer seine Seele verliert um Meinetwillen, der wird sie finden.',
        40: 'Wer euch aufnimmt, der nimmt Mich auf, und wer Mich aufnimmt, der nimmt Den auf, Der Mich ausgesandt hat.',
        41: 'Wer einen Propheten aufnimmt in eines Propheten Namen, wird eines Propheten Lohn empfangen, und wer einen Gerechten aufnimmt in eines Gerechten Namen, wird eines Gerechten Lohn empfangen.',
        42: 'Und wer einen dieser Kleinen nur mit einem Kelch kalten tränkt in eines Jüngers Namen, wahrlich, Ich sage euch, er wird seinen Lohn nicht verlieren.',
    },
    11: {
        1: 'Und es geschah, da Jesus Seine Verordnungen an Seine zwölf Jünger vollendet hatte, ging Er von dannen weiter, um in ihren Städten zu lehren und zu predigen.',
        2: 'Da aber Johannes im Kerker Christi Werke hörte, schickte er zwei seiner Jünger,',
        3: 'Und ließ Ihm sagen: Bist Du, Der da kommen soll, oder sollen wir einen andern erwarten?',
        4: 'Und Jesus antwortete und sprach zu ihnen: Ziehet hin und saget dem Johannes an, was ihr hört und seht.',
        5: 'Blinde sehen und Lahme wandeln, Aussätzige werden rein und Taube hören, Tote werden auferweckt und den Armen wird das Evangelium gepredigt.',
        6: 'Und selig ist, wer sich nicht an Mir ärgert.',
        7: 'Als diese aber hingingen, fing Jesus an zu dem Gedränge von Johannes zu sprechen: Was seid ihr hinausgegangen in die Wüste anzusehen? ein Rohr, das vom Winde hin und her geweht wird?',
        8: 'Oder was seid ihr ausgegangen zu sehen? einen Menschen mit weichen Kleidern umkleidet? Siehe, die da weiche tragen, sind in der Könige Häuser.',
        9: 'Aber was seid ihr ausgegangen zu sehen? einen Propheten? Ja, Ich sage euch: Und einen, der weit mehr ist denn ein Prophet.',
        10: 'Denn dieser ist es, von dem geschrieben ist: Siehe, Ich sende Meinen Boten aus vor Deinem Angesicht, der den Weg vor Dir zurüsten soll.',
        11: 'Wahrlich, Ich sage euch: Es ist unter denen, die von Weibern geboren sind, kein Größerer erweckt worden, denn Johannes der Täufer; aber wer im Reiche der Himmel kleiner ist, ist größer denn er.',
        12: 'Aber von den Tagen Johannes des Täufers bis hierher leidet das Reich der Himmel Gewalt, und die Gewalttätigen erhaschen es.',
        13: 'Denn alle Propheten und das Gesetz bis auf Johannes haben geweissagt.',
        14: 'Und, so ihr es aufnehmen wollt: er ist Elias, der da kommen soll.',
        15: 'Wer Ohren hat zu hören, der höre.',
        16: 'Wem aber soll Ich dieses Geschlecht vergleichen? Es ist den Kindern ähnlich, die im Markte sitzen und ihren Gesellen zurufen,',
        17: 'Und sagen: Wir haben euch gepfiffen, und ihr habt nicht getanzt. Wir haben euch geklagt, und ihr habt nicht gejammert.',
        18: 'Denn Johannes kam, aß nicht und trank nicht; und sie sagen: Er hat einen Dämon.',
        19: 'Des Menschen Sohn kam, Er aß und trank; und sie sagen: Siehe, der Mensch ist ein Fresser und Weintrinker, der Zöllner und Sünder Freund - und gerechtfertigt wurde die Weisheit von ihren Kindern.',
        20: 'Alsdann fing Er an, die Städte zu schelten, in denen die meisten Seiner Wunderkräfte geschahen, daß sie nicht Buße getan:',
        21: 'Wehe dir, Chorazin, wehe dir, Bethsaida. Wären die Wunderkräfte, die in euch geschahen, in Tyrus und Sidon geschehen, sie hätten längst in Sack und Asche Buße getan.',
        22: 'Aber Ich sage euch: Es wird Tyrus und Sidon erträglicher sein am Tage des Gerichts, denn euch.',
        23: 'Und du, Kapernaum, die du bis an den Himmel erhöht bist, du wirst bis in die Hölle hinabgestoßen werden, denn so geschehen wären in Sodom die Wunderkräfte, die in dir geschahen, wäre dasselbe wohl noch bis auf diesen Tag geblieben.',
        24: 'Aber Ich sage euch: Es wird dem Lande der Sodomer am Tage des Gerichts erträglicher sein, als dir.',
        25: 'Zur selben Zeit antwortete Jesus und sprach: Ich bekenne Dich, Vater, Herr des Himmels und der Erde, daß Du dies vor den Weisen und Verständigen verborgen und den Unmündigen geoffenbart hast;',
        26: 'Ja, Vater, daß also geschah, war wohlgefällig vor Dir.',
        27: 'Alles ist Mir von Meinem Vater überantwortet; und niemand kennt den Sohn, denn nur der Vater, noch kennt jemand den Vater, denn nur der Sohn, und wem der Sohn willens ist, es zu offenbaren.',
        28: 'Kommet her zu Mir alle, die ihr mühselig und beladen seid, und Ich will euch Ruhe schaffen.',
        29: 'Nehmet auf euch Mein Joch und lernet von Mir; denn Ich bin sanftmütig und von Herzen demütig, und ihr werdet Ruhe finden für eure Seelen.',
        30: 'Denn Mein Joch ist sanft und Meine Last ist leicht.',
    },
    12: {
        1: 'Zu der Zeit ging Jesus am Sabbath durch die Saatfelder, Seine Jünger aber waren hungrig und fingen an, Ähren auszuraufen und zu essen.',
        2: 'Da aber die Pharisäer das sahen, sprachen sie zu Ihm: Siehe, Deine Jünger tun, was nicht erlaubt ist zu tun am Sabbath.',
        3: 'Er aber sprach zu ihnen: Habt ihr nicht gelesen, was David tat, als ihn und die mit ihm waren hungerte?',
        4: 'Wie er in das Gotteshaus hineinging und die Schaubrote aß, die ihm nicht erlaubt war zu essen, noch denen, die mit ihm waren, sondern nur allein den Priestern?',
        5: 'Oder habt ihr nicht im Gesetz gelesen, daß die Priester am Sabbath im Heiligtum den Sabbath entweihen und schuldlos sind?',
        6: 'Ich aber sage euch, daß hier ist ein Größerer denn das Heiligtum.',
        7: 'Wenn ihr aber erkannt hättet, was das ist: â¬~Ich will Barmherzigkeit und nicht Opferâ¬S, so hättet ihr die Schuldlosen nicht verurteilt.',
        8: 'Denn des Menschen Sohn ist Herr auch des Sabbaths.',
        9: 'Und da Er von dannen weiterging, kam Er in ihre Synagoge.',
        10: 'Und siehe, da war ein Mensch, der hatte eine verdorrte Hand. Und sie fragten Ihn und sagten: Ist es erlaubt, am Sabbath zu heilen? auf daß sie Ihn anklagen könnten.',
        11: 'Er aber sprach zu ihnen: Welcher Mensch ist von euch, der ein Schaf hat und wenn dieses am Sabbath in eine Grube fällt, es nicht ergreift und heraufhebt.',
        12: 'Wieviel aber ist der Mensch mehr denn ein Schaf? Darum ist es erlaubt, am Sabbath Gutes zu tun.',
        13: 'Alsdann spricht Er zu dem Menschen: Recke deine Hand aus! Und er reckte sie aus, und sie war wiederhergestellt, gesund wie die andere.',
        14: 'Die Pharisäer aber gingen hinaus und hielten eine Beratung über Ihn, wie sie Ihn umbrächten.',
        15: 'Da aber Jesus es erkannte, entwich Er von dannen; und es folgte Ihm viel Gedränge nach, und Er heilte sie alle.',
        16: 'Und Er bedrohte sie, sie sollten Ihn nicht kundbar machen;',
        17: 'Auf daß erfüllt würde, was durch Jesaja, den Propheten, gesagt wird, der da spricht:',
        18: 'Siehe, das ist Mein Knecht, Den Ich erwählt habe, Mein Geliebter, an Dem Meine Seele Wohlgefallen hat. Ich will Meinen Geist auf Ihn legen, und Er soll den Völkerschaften das Gericht ansagen.',
        19: 'Nicht zanken noch aufschreien soll Er, noch soll man Seine Stimme auf den Straßen hören!',
        20: 'Ein zerknicktes Rohr wird Er nicht zerbrechen, und den glimmenden Docht wird Er nicht auslöschen, bis daß Er hervorbringet zum Siege das Gericht.',
        21: 'Und auf Seinen Namen sollen die Völkerschaften hoffen.',
        22: 'Da brachte man zu Ihm einen Besessenen, der blind und stumm war, und Er heilte ihn, so daß der Blinde und Stumme beides redete und sah.',
        23: 'Und all das Gedränge war außer sich, und sie sprachen: Ist das nicht der Sohn Davids?',
        24: 'Als es aber die Pharisäer hörten, sagten sie: Der treibt die Dämonen nicht aus, denn durch Beelzebul, den Obersten der Dämonen.',
        25: 'Jesus aber, Der ihre Gedanken sah, sprach zu ihnen: Jegliches Reich, das wider sich selbst geteilt ist, wird wüste; und jegliche Stadt oder jegliches Haus, das wider sich selbst geteilt ist, wird nicht stehen.',
        26: 'Und wenn der Satan den Satan austreibt, so ist er wider sich selbst geteilt. Wie kann dann sein Reich bestehen?',
        27: 'Und wenn Ich durch Beelzebul die Dämonen austreibe, durch wen treiben eure Söhne sie aus? Darum werden sie eure Richter sein.',
        28: 'Wenn Ich aber die Dämonen durch den Geist Gottes austreibe, so ist ja das Reich Gottes über euch herbeigekommen.',
        29: 'Oder wie kann einer in das Haus des Starken hineinkommen und ihn seiner Gefäße berauben, wofern er nicht zuvor den Starken gebunden hat? Dann kann er ihm sein Haus berauben.',
        30: 'Wer nicht mit Mir ist, der ist wider Mich, und wer nicht mit Mir sammelt, der verstreut.',
        31: 'Deshalb sage Ich euch: Jede Sünde und Lästerung mag den Menschen vergeben werden; aber die Lästerung des Geistes wird den Menschen nicht vergeben werden.',
        32: 'Und wer ein Wort spricht wider des Menschen Sohn, dem wird vergeben werden; wer aber wider den Heiligen Geist spricht, dem wird nicht vergeben werden, weder in diesem Zeitlauf, noch im zukünftigen.',
        33: 'Machet entweder den Baum gut und seine Frucht gut, oder macht den Baum faul und seine Frucht faul. Denn an der Frucht erkennt man den Baum.',
        34: 'Ihr Otterngezüchte, wie könnt ihr Gutes reden, während ihr arg seid? Denn aus dem Überfluß des Herzens redet der Mund.',
        35: 'Der gute Mensch bringt Gutes hervor aus dem guten Schatz des Herzens, und der schlechte Mensch aus dem schlechten Schatz bringt Schlechtes hervor.',
        36: 'Ich sage euch aber: Von jeder müßigen Rede, welche die Menschen reden, müssen sie Rechenschaft geben am Tage des Gerichts.',
        37: 'Denn aus deinen Worten wirst du gerechtfertigt und aus deinen Worten wirst du verurteilt werden.',
        38: 'Da antworteten einige der Schriftgelehrten und Pharisäer und sprachen: Lehrer, wir wollten ein Zeichen von Dir sehen.',
        39: 'Er aber antwortete und sprach zu ihnen: Ein schlechtes und ehebrecherisches Geschlecht trachtet nach einem Zeichen, und es soll ihm kein Zeichen gegeben werden, denn das Zeichen Jonas, des Propheten.',
        40: 'Denn wie Jonas drei Tage und drei Nächte im Bauche des Walfisches war, so wird des Menschen Sohn drei Tage und drei Nächte im Herzen der Erde sein.',
        41: 'Die Männer aus Niniveh werden im Gericht gegen dieses Geschlecht aufstehen und es verdammen; denn auf die Predigt des Jonas taten sie Buße, und siehe, hier ist mehr denn Jonas.',
        42: 'Die Königin vom Mittag wird im Gericht wider dies Geschlecht auftreten und es verdammen; denn sie kam vom Äußersten der Erde, Salomohs Weisheit zu hören. Und siehe, hier ist mehr denn Salomoh.',
        43: 'Wenn aber der unreine Geist von dem Menschen ausgeht, so geht er durch wasserlose Orte, sucht Ruhe und findet sie nicht.',
        44: 'Dann sagt er: Ich will umkehren in mein Haus, davon ich ausgegangen bin. Und wenn er kommt, findet er es leerstehend, gekehrt und geschmückt.',
        45: 'Da geht er hin und nimmt zu sich sieben andere Geister, schlechter denn er, und sie gehen ein und wohnen da, und es wird das Letzte jenes Menschen schlimmer denn sein Erstes. So wird es auch mit diesem argen Geschlecht ergehen.',
        46: 'Während Er noch so mit dem Volke redete, siehe, da standen Seine Mutter und Seine Brüder außen, und suchten mit Ihm zu reden.',
        47: 'Einer aber sprach zu Ihm: Siehe, Deine Mutter und Deine Brüder stehen draußen und suchen mit Dir zu reden.',
        48: 'Er aber antwortete und sprach zu dem, der zu Ihm sprach: Wer ist Meine Mutter, und wer sind Meine Brüder?',
        49: 'Und Er reckte Seine Hand aus über Seine Jünger und sprach: Siehe da, Meine Mutter und Meine Brüder!',
        50: 'Denn wer den Willen tut Meines Vaters in den Himmeln, der ist Mir Bruder und Schwester und Mutter.',
    },
    13: {
        1: 'An demselben Tage ging Jesus hinaus aus dem Hause und setzte Sich ans Meer.',
        2: 'Und es sammelte sich viel Gedränge zu Ihm, so daß Er in ein Schiff einstieg, Sich niederzusetzen; und all das Gedränge stand am Ufer.',
        3: 'Und Er redete vieles zu ihnen in Gleichnissen und sprach: Siehe, es ging der Sämann aus zu säen.',
        4: 'Und indem er säte, fiel einiges an den Weg; und es kam das Gevögel und fraß es auf.',
        5: 'Anderes aber fiel auf das Steinigte, wo es nicht viel Erde hatte, und ging alsbald auf, weil es nicht tiefe Erde hatte.',
        6: 'Als aber die Sonne aufging, ward es versengt; und weil es nicht Wurzel hatte, verdorrte es.',
        7: 'Anderes aber fiel auf die Dornen, und die Dornen stiegen auf und erstickten es.',
        8: 'Anderes aber fiel auf gutes Land und gab Frucht: einiges hundertfältig, einiges sechzigfältig, einiges aber dreißigfäl- tig.',
        9: 'Wer Ohren hat zu hören, der höre.',
        10: 'Und es kamen die Jünger herzu und sprachen zu Ihm: Warum redest Du zu ihnen in Gleichnissen?',
        11: 'Er aber antwortete und sprach zu ihnen: Euch ist gegeben, die Geheimnisse des Reiches der Himmel zu erkennen, jenen aber ist es nicht gegeben.',
        12: 'Denn wer da hat, dem wird gegeben, daß er Überfluß habe; wer aber nicht hat, von dem wird auch, das er hat, genommen werden.',
        13: 'Darum rede Ich in Gleichnissen zu ihnen; denn sehend sehen sie nicht, und hörend hören sie nicht, noch verstehen sie.',
        14: 'Und an ihnen wird die Weissagung des Propheten Jesajas erfüllt, die sagt: Hörend werdet ihr hören und nicht verstehen, und sehend werdet ihr sehen und nicht vernehmen.',
        15: 'Denn das Herz dieses Volkes ist verstockt, und mit ihren Ohren hören sie schwer, und sie drücken die Augen zu, damit sie nicht sehen mit den Augen und hören mit den Ohren und mit dem Herzen verstehen und umkehren und Ich sie gesund mache.',
        16: 'Selig aber sind eure Augen, daß sie sehen, und eure Ohren, daß sie hören;',
        17: 'Denn wahrlich, Ich sage euch, daß viele Propheten und Gerechte haben begehrt zu sehen, was ihr seht, und haben es nicht gesehen, und zu hören, was ihr hört, und haben es nicht gehört.',
        18: 'So hört ihr denn das Gleichnis von dem Sämann!',
        19: 'Wenn jemand das Wort von dem Reiche hört und nicht versteht, so kommt der Arge und erhascht, was in seinem Herzen gesät ist. Dieser ist es, der an dem Wege gesät ist.',
        20: 'Der aber, der auf das Steinigte gesät worden, ist der, welcher das Wort hört, und es alsbald mit Freuden aufnimmt.',
        21: 'Aber er hat keine Wurzel in sich, sondern ist zeitweilig; so aber Trübsal oder Verfolgung geschieht um des Wortes willen, so ärgert er sich alsbald.',
        22: 'Der aber, der in die Dornen gesät worden, ist der, welcher das Wort hört; und die Sorge dieses Zeitlaufs, und der Betrug des Reichtums erstickt das Wort, und es wird unfruchtbar.',
        23: 'Der aber auf das gute Land gesät ist, ist der, so das Wort hört und versteht, und der dann Frucht trägt; und der eine bringt hundertfältig, der andere aber sechzigfältig, der andere aber dreißigfältig.',
        24: 'Er legte ihnen ein anderes Gleichnis vor und sprach: Das Reich der Himmel gleicht einem Menschen der guten Samen in sein Feld säte.',
        25: 'Während aber die Menschen schlummerten, kam sein Feind und säte Unkraut mitten unter den Weizen und ging hin.',
        26: 'Als aber die Saat hervorsproßte und Frucht brachte, da erschien auch das Unkraut.',
        27: 'Die Knechte aber des Hausherrn kamen herzu und sprachen zu ihm: Herr, hast du nicht guten Samen in dein Feld gesät? Woher hat er nun das Unkraut?',
        28: 'Er aber sprach zu ihnen: Ein feindseliger Mensch hat das getan. Die Knechte aber sprachen zu ihm: Willst du nun, daß wir hingehen und es zusammenlesen?',
        29: 'Er aber sprach: Nein, auf daß ihr nicht, wenn ihr das Unkraut zusammenleset, zugleich damit den Weizen ausreutet.',
        30: 'Lasset beide zusammen wachsen bis zur Ernte, und zur Zeit der Ernte will ich den Schnittern sagen: Leset erst das Unkraut zusammen und bindet es in Bündel, um es zu verbrennen; den Weizen aber sammelt in meine Scheune.',
        31: 'Ein anderes Gleichnis legte Er ihnen vor und sagte: Das Reich der Himmel ist gleich einem Senfkorn, das ein Mensch nahm und auf sein Feld säte;',
        32: 'Welches zwar kleiner ist als alle Samen, wenn es aber erwächst, ist es das größte unter den Gartenkräutern, und wird ein Baum, so daß das Gevögel des Himmels kommt und in seinen Zweigen nistet.',
        33: 'Ein anderes Gleichnis redete Er zu ihnen: Das Reich der Himmel ist gleich einem Sauerteig, den ein Weib nahm und in drei Maß Mehl barg, bis daß es ganz durchsäuert war.',
        34: 'Dieses alles redete Jesus in Gleichnisse zu dem Volk, und ohne Gleichnis redete Er nicht zu ihnen.',
        35: 'Damit erfüllt würde, was durch den Propheten gesagt ist, der da spricht: Ich will Meinen Mund auftun in Gleichnissen. Ich will aussprechen, was seit Gründung der Welt verborgen war.',
        36: 'Da entließ Jesus das Volk und kam in das Haus, und Seine Jünger kamen zu Ihm und sprachen: Deute uns das Gleichnis von dem Unkraut des Feldes.',
        37: 'Er aber antwortete und sprach zu ihnen: Der den guten Samen sät, ist des Menschen Sohn.',
        38: 'Das Feld ist die Welt. Der gute Same, das sind die Söhne des Reiches; das Unkraut aber sind die Söhne des Argen.',
        39: 'Der Feind aber, der es säte, ist der Teufel. Die Ernte aber ist die Vollendung des Zeitlaufs; die Schnitter aber sind die Engel.',
        40: 'Wie nun das Unkraut zusammengelesen und im Feuer verbrannt wird, so wird es bei der Vollendung dieses Zeitlaufs geschehen.',
        41: 'Der Sohn des Menschen wird Seine Engel aussenden, und sie werden aus Seinem Reiche zusammenlesen alle Ärgernisse und die da Unrecht tun;',
        42: 'Und werden sie in den Feuerofen werfen. Dort wird sein Heulen und Zähneknirschen.',
        43: 'Dann werden die Gerechten hervorleuchten, wie die Sonne, im Reiche ihres Vaters. Wer Ohren hat zu hören, der höre.',
        44: 'Wiederum gleicht das Reich der Himmel einem Schatze, der in dem Felde verborgen liegt, den ein Mensch findet und verbirgt und in seiner Freude hingeht und alles, was er hat, verkauft und dieses Feld kauft.',
        45: 'Wiederum ist das Reich der Himmel gleich einem Menschen, einem Kaufmann, der schöne Perlen sucht.',
        46: 'Wenn der eine kostbare Perle gefunden, geht er hin, verkauft alles, was er hat, und kauft dieselbige.',
        47: 'Wiederum ist das Reich der Himmel gleich einem Zugnetze, das ins Meer geworfen ward und allerlei Gattung zusammensammelte.',
        48: 'Welches sie, wenn es voll ist, ans Ufer heraufziehen, und sich niedersetzen und lesen die guten zusammen in Gefäße, die faulen aber werfen sie hinaus.',
        49: 'So wird es sein bei der Vollendung des Zeitlaufs. Die Engel werden ausgehen und ausscheiden die Schlechten aus der Mitte der Gerechten.',
        50: 'Und werden sie in den Feuerofen werfen. Dort wird sein Weinen und Zähneknirschen.',
        51: 'Spricht zu ihnen Jesus: Habt ihr das alles verstanden? Sie sagen zu Ihm: Ja, Herr.',
        52: 'Er aber sprach zu ihnen: Deshalb ist jeder Schriftgelehrte, der für das Reich der Himmel unterrichtet worden, gleich einem Menschen, einem Hausherrn, der aus seinem Schatz Neues und Altes hervorbringt.',
        53: 'Und es geschah, da Jesus diese Gleichnisse vollendet hatte, begab Er Sich von dannen,',
        54: 'Und kam in Seine Vaterstadt und lehrte sie in ihrer Synagoge, also daß sie staunten und sagten: Woher hat dieser solche Weisheit und Wunderkräfte?',
        55: 'Ist Der nicht des Zimmermanns Sohn? Wird nicht Seine Mutter Maria genannt und Seine Brüder Jakobus und Joses, und Simon, und Judas?',
        56: 'Und sind nicht Seine Schwestern alle bei uns? Woher kommt Ihm denn alles dies?',
        57: 'Und sie ärgerten sich an Ihm. Jesus aber sprach zu ihnen: Ein Prophet ist nicht ohne Ehre, außer in seiner Vaterstadt und in seinem Hause.',
        58: 'Und Er tat daselbst nicht viele Wundertaten um ihres Unglaubens willen.',
    },
    14: {
        1: 'Zu der Zeit hörte Herodes, der Vierfürst, das Gerücht von Jesus;',
        2: 'Und er sprach zu seinen Knechten: Dies ist Johannes, der Täufer. Der ist von den Toten auferweckt, und darum wirken solche Wunderkräfte ihn Ihm.',
        3: 'Denn Herodes hatte lassen Johannes ergreifen, ihn binden und ins Gefängnis legen wegen der Herodias, des Weibes seines Bruders Philippus.',
        4: 'Denn Johannes sagte ihm: Es ist dir nicht erlaubt, daß du sie habest.',
        5: 'Und da er ihn töten wollte, fürchtete er sich vor dem Volke, denn sie hielten ihn für einen Propheten.',
        6: 'Da sie aber das Geburtsfest des Herodes begingen, tanzte die Tochter der Herodias in ihrer Mitte und gefiel dem Herodes;',
        7: 'Darum beteuerte er mit einem Eide, ihr zu geben, um was sie nur bitten würde.',
        8: 'Sie aber, von ihrer Mutter angetrieben, spricht: Gib mir her auf einer Platte das Haupt Johannes, des Täufers.',
        9: 'Und der König ward betrübt, aber wegen des Eides und derer, die mit zu Tische lagen, befahl er, es ihr zu geben.',
        10: 'Und er schickte hin und ließ Johannes im Gefängnis enthaupten.',
        11: 'Und sein Haupt ward auf einer Platte gebracht und dem Mägdlein gegeben, und sie brachte es ihrer Mutter.',
        12: 'Und seine Jünger kamen herbei, hoben den Leib auf und begruben ihn, und kamen, und sagten es Jesus an.',
        13: 'Und wie Jesus das hörte, entwich Er von dannen in einem Schiff an einen wüsten Ort besonders. Und als das Gedränge es hörte, folgten sie Ihm zu Fuß aus den Städten nach.',
        14: 'Und als Er ausstieg, sah Er das viele Gedränge, und es jammerte Ihn derselben, und Er heilte ihre Siechen.',
        15: 'Als es aber Abend ward, kamen Seine Jünger zu ihm und sprachen: Der Ort ist wüste, und die Stunde ist schon vergangen. Entlasse das Gedränge, daß sie in die Flecken hingehen und sich Speise kaufen.',
        16: 'Jesus aber sprach zu ihnen: Sie haben nicht nötig, wegzugehen. Gebt ihr ihnen zu essen.',
        17: 'Sie aber sagten zu Ihm: Wir haben nichts hier, denn fünf Brote und zwei Fische.',
        18: 'Er aber sprach: Bringt sie zu Mir hierher.',
        19: 'Und Er befahl dem Volke, sich auf das Gras hinzulegen, nahm die fünf Brote und die zwei Fische, blickte auf zum Himmel, dankte, brach und gab den Jüngern die Brote, die Jünger aber dem Volke.',
        20: 'Und es aßen alle und wurden satt, und sie hoben auf, was übrigblieb an Brocken, zwölf volle Körbe.',
        21: 'Die aber gegessen hatten, waren bei fünftausend Männer, ohne Weiber und Kinder.',
        22: 'Und alsbald nötigte Jesus die Jünger in das Fahrzeug einzusteigen und vor Ihm hinüberzufahren, bis daß Er das Volk entlassen hätte.',
        23: 'Und nachdem Er das Volk entlassen, stieg Er auf den Berg besonders, um zu beten. Als es aber Abend ward, war Er daselbst allein.',
        24: 'Das Fahrzeug aber war schon mitten auf dem Meer und litt Not von den Wellen; denn der Wind war entgegen.',
        25: 'Aber um die vierte Wache der Nacht kam Jesus hin zu ihnen, wandelnd auf dem Meere.',
        26: 'Und da die Jünger Ihn auf dem Meere wandeln sahen, erbebten sie und sagten: Es ist ein Gespenst; und schrien auf vor Furcht.',
        27: 'Alsbald aber redete Jesus zu ihnen und sprach: Seid getrost, Ich bin es! Fürchtet euch nicht!',
        28: 'Petrus aber antwortete Ihm und sprach: Herr, bist Du es, so befiehl mir, zu Dir auf das Wasser zu kommen.',
        29: 'Er aber sprach: Komm! Und Petrus stieg hinab aus dem Fahrzeug und wandelte auf dem Wasser, um zu Jesus zu kommen.',
        30: 'Da er aber den starken Wind sah, fürchtete er sich, und da er anfing, zu versinken, schrie er und sprach: Herr, rette mich!',
        31: 'Alsbald aber reckte Jesus die Hand aus, ergriff ihn und sprach zu ihm: Kleingläubiger, warum zweifeltest du?',
        32: 'Und als sie ins Schiff eingestiegen waren, legte sich der Wind.',
        33: 'Die im Fahrzeug aber kamen, beteten Ihn an und sprachen: Du bist wahrlich Gottes Sohn.',
        34: 'Und sie fuhren hinüber und kamen in das Land Gennesaret.',
        35: 'Und als die Leute an selbigem Orte Ihn erkannten, sandten sie in jene ganze Umgegend aus und brachten alle Leidende zu Ihm.',
        36: 'Und flehten Ihn an, daß sie nur Seines Kleides Saum berührten, und so viele Ihn berührten, wurden gerettet.',
    },
    15: {
        1: 'Da kamen die Schriftgelehrten und Pharisäer aus Jerusalem herbei zu Jesus und sprachen:',
        2: 'Warum übertreten Deine Jünger die Überlieferung der Ältesten? Denn sie waschen ihre Hände nicht, wenn sie Brot essen.',
        3: 'Er aber antwortete und sprach zu ihnen: Warum übertretet auch ihr das Gebot Gottes, um eurer Überlieferung willen?',
        4: 'Denn Gott hat geboten und gesagt: Ehre Vater und Mutter; und wer Vater oder Mutter flucht, der soll des Todes sterben.',
        5: 'Ihr aber sagt: Wer zum Vater oder zur Mutter sagt: Es ist eine Gabe, was du von mir zum Nutzen gehabt hättest; der wird sicherlich nicht seinen Vater oder seine Mutter ehren.',
        6: 'Und ihr habt so das Gebot Gottes um eurer Überlieferung willen ungültig gemacht.',
        7: 'Ihr Heuchler, schön hat von euch Jesajas geweissagt und gesprochen:',
        8: 'Es nahet Mir dieses Volk mit dem Munde und ehret Mich mit den Lippen; aber ihr Herz ist weit weg von Mir.',
        9: 'Aber vergeblich verehren sie Mich, weil sie solche Lehre lehren, die Gebote der Menschen sind.',
        10: 'Und Er rief das Volk zu Sich und sprach zu ihnen: Höret und verstehet es!',
        11: 'Nicht was zum Munde eingeht, macht den Menschen gemein, sondern was vom Munde ausgeht, das macht den Menschen gemein.',
        12: 'Da kamen Seine Jünger herbei und sagten zu Ihm: Weißt Du, daß die Pharisäer, da sie das Wort hörten, sich ärgerten?',
        13: 'Er aber antwortete und sprach: Jegliche Pflanze, die Mein himmlischer Vater nicht gepflanzt hat, wird ausgereutet werden.',
        14: 'Lasset sie. Sie sind blinde Wegweiser der Blinden. Wenn aber ein Blinder einem Blinden den Weg weiset, werden beide in die Grube fallen.',
        15: 'Petrus aber antwortete und sprach zu Ihm: Deute uns dieses Gleichnis.',
        16: 'Er aber sprach: Dann seid auch ihr unverständig?',
        17: 'Begreifet ihr noch nicht, daß alles, was zum Munde eingeht, das geht in den Bauch, und wird in den Abzug geworfen?',
        18: 'Was aber vom Munde ausgeht, das kommt aus dem Herzen, und das macht den Menschen gemein.',
        19: 'Denn aus dem Herzen kommen hervor schlechte Gedanken, Morde, Ehebrüche, Buhlereien, Diebereien, falsche Zeugnisse, Lästerungen.',
        20: 'Das ist es, was den Menschen gemein macht; das Essen mit ungewaschenen Händen aber macht den Menschen nicht gemein.',
        21: 'Und Jesus ging aus von dannen und entwich in die Gegend von Tyrus und Sidon.',
        22: 'Und siehe, ein kanaanitisches Weib kam von jenen Grenzen heraus, schrie Ihm laut zu und sprach: Erbarme Dich meiner, Herr, Du Sohn Davids, meine Tochter ist übel besessen.',
        23: 'Er aber antwortete ihr kein Wort. Und Seine Jünger kamen zu Ihm, baten Ihn und sagten: Entlasse sie; denn sie schreit uns nach.',
        24: 'Er aber antwortete und sprach: Ich bin nur abgesandt zu den verlorenen Schafen des Hauses Israel.',
        25: 'Sie aber kam, fiel vor Ihm nieder und sprach: Herr, hilf mir.',
        26: 'Er aber antwortete und sprach: Es ist nicht schön, daß man der Kinder Brot nehme, und werfe es vor die Hündchen.',
        27: 'Sie aber sprach: Ja, Herr, und doch essen die Hündchen von den Brosamen, die von ihrer Herren Tische fallen.',
        28: 'Da antwortete Jesus und sprach zu ihr: O Weib, dein Glaube ist groß. Dir geschehe, wie du willst. Und ihre Tochter ward gesund zur selbigen Stunde.',
        29: 'Und Jesus ging weiter von dannen und kam an das Meer von Galiläa und stieg auf den Berg hinauf und setzte Sich allda.',
        30: 'Und es kam zu Ihm viel Volks, und sie hatten mit sich Lahme, Blinde, Stumme, Krüppel und viele andere und warfen sie dahin zu Seinen Füßen, und Er heilte sie.',
        31: 'So daß sich das Volk verwunderte, da sie sahen Stumme reden, Krüppel gesund werden, Lahme wandeln und Blinde sehen; und sie verherrlichten den Gott Israels.',
        32: 'Jesus aber rief Seine Jünger herbei und sprach: Mich jammert des Volkes, daß sie nun schon drei Tage bei Mir verharren und nichts zu essen haben; und ungegessen will Ich sie nicht von Mir lassen, auf daß sie nicht auf dem Wege verschmachten.',
        33: 'Und Seine Jünger sprechen zu Ihm: Woher soll uns in der Wüste so viel Brot werden, um so viel Volk zu sättigen?',
        34: 'Und Jesus spricht zu ihnen: Wie viele Brote habt ihr? Sie aber sagten: Sieben und einige Fischlein.',
        35: 'Und Er befahl dem Volk, sich auf die Erde niederzulassen.',
        36: 'Und Er nahm die sieben Brote und die Fische, dankte, brach sie und gab sie Seinen Jüngern, die Jünger aber dem Volke.',
        37: 'Und sie aßen alle und wurden satt; und hoben auf das übrige der Brocken, sieben volle Weidenkörbe.',
        38: 'Die aber gegessen hatten, waren viertausend Männer ohne die Weiber und Kinder.',
        39: 'Und da Er das Volk entlassen hatte, stieg Er ein in das Fahrzeug und kam in die Grenzen von Magdala.',
    },
    16: {
        1: 'Und die Pharisäer und Sadduzäer kamen herzu, Ihn zu versuchen, und baten, daß Er ihnen ein Zeichen vom Himmel zeige.',
        2: 'Er antwortete ihnen aber und sprach: Wenn es Abend wird, sprechet ihr: Gut Wetter! denn der Himmel rötet sich;',
        3: 'Und am Morgen: Sturmwetter heute! denn der Himmel rötet sich und ist düster. Ihr Heuchler, das Aussehen des Himmels wisset ihr zu unterscheiden, aber die Zeichen der Zeit könnet ihr nicht?',
        4: 'Ein arges und ehebrecherisches Geschlecht sucht ein Zeichen; und es soll ihm kein Zeichen gegeben werden, als das Zeichen Jonas, des Propheten. Und Er verließ sie und ging weg.',
        5: 'Und als Seine Jünger hinüberkamen, hatten sie vergessen, Brote mit sich zu nehmen.',
        6: 'Jesus aber sprach zu ihnen: Sehet zu, daß ihr euch vor dem Sauerteig der Pharisäer und Sadduzäer in acht nehmet.',
        7: 'Sie aber bedachten bei sich und sagten: Das ist es, daß wir kein Brot mit uns genommen.',
        8: 'Jesus aber erkannte es und sagte: Was bedenket ihr bei euch, ihr Kleingläubigen, daß ihr kein Brot mit euch genommen?',
        9: 'Begreifet ihr noch nicht? Gedenket ihr nicht der fünf Brote für die Fünftausend, und wieviel Körbe ihr aufnahmet?',
        10: 'Auch nicht an die sieben Brote für die Viertausend, und wieviel Weidenkörbe ihr da aufnahmet?',
        11: 'Wie? Begreifet ihr nicht, daß Ich nicht wegen dem Brote zu euch sagte, ihr sollet euch vor dem Sauerteig der Pharisäer und Sadduzäer in acht nehmen?',
        12: 'Jetzt verstanden sie, daß Er ihnen nicht sagte, sie sollten sich vor dem Sauerteig des Brotes in acht nehmen, sondern vor der Lehre der Pharisäer und Sadduzäer.',
        13: 'Da Jesus aber in die Gegend von Cäsarea Philippi kam, fragte Er Seine Jünger und sagte: Wer sagen die Menschen, daß des Menschen Sohn sei?',
        14: 'Sie aber sagten: Die einen sagen, Du seist Johannes der Täufer, andere aber Elias; aber andere, Jeremias, oder der Propheten einer.',
        15: 'Spricht Er zu ihnen: Wer sagt aber ihr, daß Ich sei?',
        16: 'Simon Petrus aber antwortete und sprach: Du bist Christus, der Sohn des lebendigen Gottes.',
        17: 'Und Jesus antwortete und sprach zu ihm: Selig bist du, Simon Bar Jona; denn Fleisch und Blut hat dir das nicht geoffenbart, sondern Mein Vater in den Himmeln.',
        18: 'Und Ich aber sage dir: Du bist Petrus, und auf diesen Felsen werde Ich Meine Kirche bauen, und die Tore der Hölle sollen sie nicht überwältigen.',
        19: 'Und Ich will dir die Schlüssel des Reiches der Himmel geben; und was du auf Erden binden wirst, das soll in den Himmeln gebunden sein; und was du auf Erden lösen wirst, das soll in den Himmeln gelöst sein.',
        20: 'Da verbot Er Seinen Jüngern, sie sollten niemand sagen, daß Er Jesus der Christus sei.',
        21: 'Von da an fing Jesus an, Seinen Jüngern zu zeigen, daß Er müßte hingehen nach Jerusalem, und von den Ältesten und Hohenpriestern und Schriftgelehrten vieles leiden, und getötet werden und am dritten Tage auferweckt werden.',
        22: 'Und Petrus nahm Ihn zu sich und fing an, Ihn zu bedrohen und sprach: Herr, schone Dich! das geschehe Dir nur nicht.',
        23: 'Er aber wandte Sich und sagte zu Petrus: Gehe hinweg, hinter Mich, Satan, du bist mir ein Ärgernis, denn du sinnest nicht, was von Gott sondern was von Menschen ist.',
        24: 'Dann sprach Jesus zu Seinen Jüngern: Wer Mir folgen will, verleugne sich selbst, und nehme sein Kreuz auf sich und folge Mir nach.',
        25: 'Denn wer seine Seele retten will, der wird sie verlieren; wer aber seine Seele verliert um Meinetwillen, der wird sie finden.',
        26: 'Denn was nützete es dem Menschen, so er die ganze Welt gewönne, nähme aber Schaden an seiner Seele? Oder was kann der Mensch geben zur Lösung seiner Seele?',
        27: 'Denn des Menschen Sohn wird kommen in der Herrlichkeit Seines Vaters mit Seinen Engeln, und dann wird Er einem jeglichen nach seinem Tun vergelten.',
        28: 'Wahrlich, Ich sage euch: Es sind welche, die hier stehen, die den Tod nicht schmecken werden, bis daß sie des Menschen Sohn in Seinem Reiche kommen sehen.',
    },
    17: {
        1: 'Und nach sechs Tagen nimmt Jesus zu Sich Petrus und Jakobus und Johannes, seinen Bruder, und bringt sie hinauf auf einen hohen Berg besonders.',
        2: 'Und Er ward verwandelt vor Ihnen, und Sein Angesicht leuchtete wie die Sonne, und Seine Kleider wurden weiß wie das Licht.',
        3: 'Und siehe, es erschien ihnen Moses und Elias, und sie unterredeten sich mit Ihm.',
        4: 'Petrus aber antwortete und sprach zu Jesus: Herr, hier ist uns gut sein. Wenn Du willst, so wollen wir hier drei Hütten machen, Dir eine, und Moses eine, und Elias eine.',
        5: 'Während er noch redete, siehe, da überschattete sie eine lichte Wolke; und siehe, eine Stimme aus der Wolke sprach: Dies ist Mein geliebter Sohn, an Dem Ich Wohlgefallen habe: Ihn sollt ihr hören!',
        6: 'Und da das die Jünger hörten, fielen sie auf ihr Angesicht und fürchteten sich sehr.',
        7: 'Jesus aber kam herzu und berührte sie und sprach: Stehet auf und fürchtet euch nicht.',
        8: 'Als sie aber ihre Augen aufhoben, sahen sie niemand als Jesus allein.',
        9: 'Und wie sie vom Berge herabstiegen, gebot ihnen Jesus und sprach: Saget niemand von dem Gesichte, bis daß des Menschen Sohn von den Toten auferstanden ist.',
        10: 'Und Seine Jünger fragten Ihn und sprachen: Was sagen denn die Schriftgelehrten, daß Elias zuvor kommen müsse?',
        11: 'Jesus aber antwortete und sprach zu ihnen: Elias kommt zwar zuerst, und wird alles herstellen.',
        12: 'Aber Ich sage euch: Elias ist schon gekommen; und sie erkannten ihn nicht, sondern taten mit ihm, was sie wollten. Also wird auch des Menschen Sohn von ihnen leiden.',
        13: 'Da verstanden die Jünger, daß Er zu ihnen von Johannes dem Täufer sprach.',
        14: 'Und da sie zum Gedränge kamen, kam ein Mensch zu Ihm, fiel vor Ihm auf die Knie,',
        15: 'Und sprach: Herr, erbarme Dich meines Sohnes; denn er ist mondsüchtig und hat ein böses Leiden; denn oft fällt er ins Feuer, und oft ins Wasser.',
        16: 'Und ich brachte ihn zu Deinen Jüngern, und sie konnten ihn nicht heilen.',
        17: 'Jesus aber antwortete und sprach: O ihr ungläubiges und verkehrtes Geschlecht, wie lange soll Ich bei euch sein? Wie lange soll Ich euch ertragen? Bringet Mir ihn her.',
        18: 'Und Jesus bedrohte ihn, und der Dämon fuhr aus von ihm. Und der Knabe war geheilt von selbiger Stunde an.',
        19: 'Da kamen die Jünger zu Jesus besonders und sprachen: Warum konnten wir ihn nicht austreiben?',
        20: 'Jesus aber sprach zu ihnen: Eures Unglaubens wegen; denn wahrlich, Ich sage euch, wenn ihr Glauben habt wie ein Senfkorn, so möget ihr zu diesem Berge sagen: Versetze dich von hinnen dorthin, so wird er sich versetzen, und nichts wird euch unmöglich sein.',
        21: 'Diese Gattung aber fährt nur durch Beten und Fasten aus.',
        22: 'Während sie aber in Galiläa umherwandelten, sprach Jesus zu ihnen: Es wird geschehen, daß des Menschen Sohn in die Hände der Menschen überantwortet wird.',
        23: 'Und sie werden Ihn töten, aber am dritten Tage wird Er auferweckt werden. Und sie wurden sehr betrübt.',
        24: 'Als sie aber nach Kapernaum kamen, kamen die, so die Doppeldrachmen einnahmen, herzu zu Petrus und sprachen: Entrichtet euer Lehrer die Doppeldrachme?',
        25: 'Er sagt: Ja. Und als er ins Haus hineinkam, kam ihm Jesus zuvor und sprach: Was meinst du, Simon? Von wem nehmen die Könige der Erde Zoll oder Steuer? Von ihren Söhnen, oder von den Fremden?',
        26: 'Spricht zu Ihm Petrus: Von den Fremden. Da sprach Jesus zu ihm: Also sind die Söhne frei.',
        27: 'Damit wir sie aber nicht ärgern, gehe du ans Meer, wirf die Angel und nimm den ersten Fisch, der heraufsteigt, tue ihm den Mund auf und du wirst einen Stater finden. Nimm ihn und gib ihnen den für Mich und für dich.',
    },
    18: {
        1: 'Zur selben Stunde kamen die Jünger zu Jesus und sagten: Wer ist wohl der Größte im Reiche der Himmel?',
        2: 'Und Jesus rief eine Kindlein zu Sich und stellte es in ihre Mitte,',
        3: 'Und sprach: Wahrlich, Ich sage euch: Wenn ihr nicht umkehret und werdet wie die Kindlein, so werdet ihr mitnichten in das Reich der Himmel kommen.',
        4: 'Wer nun sich selbst erniedrigt, wie dieses Kindlein, der ist der Größte im Reich der Himmel;',
        5: 'Und wer aufnimmt ein solches Kindlein in Meinem Namen, der nimmt Mich auf.',
        6: 'Wer aber ärgert einen dieser Kleinen, die an Mich glauben, dem wäre zuträglicher, daß ein Eselsmühlstein an seinen Hals gehängt und er versenkt würde in des Meeres Tiefe.',
        7: 'Wehe der Welt, der Ärgernisse halben. Es ist wohl notwendig, daß Ärgernisse kommen; aber wehe demselbigen Menschen, durch den das Ärgernis kommt.',
        8: 'Ärgert dich aber deine Hand, oder dein Fuß, so haue sie ab und wirf sie von dir; es ist dir besser, lahm oder ein Krüppel zum Leben einzugehen, als daß du zwei Hände oder zwei Füße habest und werdest ins ewige Feuer geworfen.',
        9: 'Und so dein Auge dich ärgert, reiß es aus und wirf es von dir: es ist dir besser, einäugig zum Leben einzugehen, als daß du zwei Augen habest und werdest in die Hölle des Feuers geworfen.',
        10: 'Sehet zu, daß ihr nicht einen dieser Kleinen verachtet; denn Ich sage euch, ihre Engel schauen allezeit in den Himmeln das Angesicht Meines Vaters in den Himmeln.',
        11: 'Denn des Menschen Sohn ist gekommen, das Verlorene zu retten.',
        12: 'Was meint ihr? Wenn ein Mensch hundert Schafe hätte, und eines davon geht irre, würde er nicht die neunundneunzig auf den Bergen lassen und hingehen und suchen, das da irre gegangen ist?',
        13: 'Und wenn es sich begibt, daß er dasselbe findet, wahrlich, Ich sage euch: er freut sich über demselben mehr, als über die neunundneunzig, die nicht irre gegangen sind.',
        14: 'So ist es nicht der Wille vor eurem Vater in den Himmeln, daß eines dieser Kleinen verloren werde.',
        15: 'Sündigt aber dein Bruder gegen dich, so gehe hin und rüge ihn zwischen dir und ihm allein. Hört er auf dich, so hast du deinen Bruder gewonnen.',
        16: 'Hört er aber nicht auf dich, so nimm noch einen oder zwei mit dir, auf daß die ganze Rede auf zweier oder dreier Zeugen Mund bestehe.',
        17: 'Hört er aber auch sie nicht, so sage es der Gemeinde. Hört er aber auch auf die Gemeinde nicht, so sei er dir wie der Heide und der Zöllner.',
        18: 'Wahrlich, Ich sage euch: Was ihr auf Erden binden werdet, das soll im Himmel gebunden sein, und was ihr auf Erden lösen werdet, soll auch im Himmel gelöst sein.',
        19: 'Wiederum sage Ich euch: Wenn zwei von euch auf Erden übereinstimmen über irgendeine Sache, um was sie bitten, so soll es ihnen geschehen von Meinem Vater in den Himmeln.',
        20: 'Denn wo zwei oder drei versammelt sind in Meinem Namen, da bin Ich mitten unter ihnen.',
        21: 'Da kam Petrus zu Ihm und sprach: Wie oft mag mein Bruder wider mich sündigen, und ich ihm vergeben? Bis zu sieben Mal?',
        22: 'Spricht zu ihm Jesus: Ich sage dir, nicht bis zu sieben Mal, sondern bis zu siebzig mal sieben.',
        23: 'Darum ist das Reich der Himmel gleich einem Menschen, einem Könige, der mit seinen Knechten Rechnung abhalten wollte.',
        24: 'Da er aber anfing abzurechnen, ward einer vor ihn gebracht, ein Schuldner von zehntausend Talenten.',
        25: 'Da er aber nicht hatte, zu bezahlen, befahl sein Herr, ihn und sein Weib und die Kinder und alles, das er hatte, zu verkaufen und zu bezahlen.',
        26: 'Da fiel denn der Knecht nieder, betete ihn an und sprach: Herr, habe Langmut mit mir, und ich will dir alles bezahlen.',
        27: 'Da jammerte es aber den Herrn desselbigen Knechts, und er gab ihn los und vergab ihm das Anlehen.',
        28: 'Wie aber dieser Knecht hinauskam, fand er einen seiner Mitknechte, der ihm hundert Denare schuldete; und er ergriff ihn, würgte ihn und sprach: Bezahle mir, was du mir schuldig bist.',
        29: 'Der Mitknecht fiel denn nieder, flehte ihn an und sprach: Habe Langmut mit mir, und ich will dir alles bezahlen.',
        30: 'Er aber wollte nicht, sondern ging hin und warf ihn ins Gefängnis, bis daß er bezahlete, was er schuldig war.',
        31: 'Da aber seine Mitknechte sahen, was geschehen war, wurden sie sehr betrübt, und sie gingen und berichteten ihrem Herrn alles, was geschehen war.',
        32: 'Da rief ihn sein Herr zu sich und sprach zu ihm: Du schlechter Knecht, ich habe dir alle jene Schuld vergeben, weil du mich anflehtest;',
        33: 'Hättest du nicht auch Erbarmen mit deinem Mitknechte haben sollen, wie auch ich mich deiner erbarmte?',
        34: 'Und sein Herr ward zornig und überantwortete ihn den Peinigern, bis daß er alles bezahlete, was er ihm schuldete.',
        35: 'So wird auch Mein himmlischer Vater euch tun, wenn ihr nicht vergebet von eurem Herzen ein jeglicher seinem Bruder seine Fehler.',
    },
    19: {
        1: 'Und es geschah, als Jesus diese Worte vollendet hatte, begab Er Sich aus Galiläa und kam in die Grenzen Judäas jenseits des Jordans.',
        2: 'Und es folgte Ihm viel Volk nach, und Er heilte sie daselbst.',
        3: 'Und es kamen herzu zu Ihm die Pharisäer, versuchten Ihn und sagten zu Ihm: Ist es dem Menschen erlaubt, aus jeglicher Ursache sich von seinem Weibe zu scheiden?',
        4: 'Er aber antwortete und sprach zu ihnen: Habt ihr nicht gelesen, daß Er, Der sie von Anfang gemacht hat, sie als Mann und Weib gemacht hat?',
        5: 'Und Er sprach: Darum soll der Mensch Vater und Mutter verlassen und seinem Weibe anhangen. Und die zwei werden ein Fleisch sein.',
        6: 'So daß sie nicht mehr zwei, sondern ein Fleisch sind. Was nun Gott zusammengefügt, daß soll der Mensch nicht trennen.',
        7: 'Sprechen sie zu Ihm: Warum hat dann Moses geboten, einen Scheidebrief zu geben und sie zu entlassen?',
        8: 'Er spricht zu ihnen: Um eurer Hartherzigkeit willen hat euch Moses gestattet, eure Weiber zu entlassen; von Anfang an aber ist es nicht also gewesen.',
        9: 'Ich sage euch aber: Wer sein Weib entläßt, es sei denn um der Buhlerei willen, und eine andere freit, der bricht die Ehe, und wer eine Geschiedene freit, bricht die Ehe.',
        10: 'Sprechen zu Ihm Seine Jünger: Ist die Sache des Menschen mit dem Weibe so, dann ist es nicht zuträglich, zu freien.',
        11: 'Er aber sprach zu ihnen: Nicht alle fassen dieses Wort, sondern die, denen es gegeben ist.',
        12: 'Denn es sind Verschnittene, die von der Mutter Leib so geboren wurden, und sind Verschnittene, die von den Menschen verschnitten wurden, und sind Verschnittene, die um des Reiches der Himmel willen sich selbst verschnitten haben. Wer es fassen kann, der fasse es!',
        13: 'Da wurden Kindlein zu Ihm gebracht, auf daß Er die Hände auf sie legete und betete; die Jünger aber bedrohten sie.',
        14: 'Jesus aber sprach: Lasset die Kindlein und wehret ihnen nicht zu Mir zu kommen; denn solcher ist das Reich der Himmel.',
        15: 'Und da Er die Hände auf sie gelegt, zog Er von dannen.',
        16: 'Und siehe, es kam einer herzu und sprach zu Ihm: Guter Lehrer, was soll ich Gutes tun, auf daß ich ewiges Leben habe?',
        17: 'Er aber sagte ihm: Was heißest du Mich gut? Niemand ist gut, denn der eine Gott. Willst du aber ins Leben eingehen, so halte die Gebote.',
        18: 'Er spricht zu Ihm: Welche? Jesus aber sprach: Das: du sollst nicht morden; du sollst nicht ehebrechen; du sollst nicht stehlen; du sollst kein falsch Zeugnis geben.',
        19: 'Ehre Vater und Mutter; und du sollst deinen Nächsten lieben, wie dich selbst.',
        20: 'Spricht zu Ihm der Jüngling: Alles das habe ich gehalten von meiner Jugend auf. Was mangelt mir noch?',
        21: 'Jesus sprach zu ihm: Wenn du willst vollkommen sein, gehe hin, verkaufe, was du hast, und gib den Armen, und du wirst einen Schatz im Himmel haben, und komm her, folge Mir nach!',
        22: 'Als aber der Jüngling das Wort hörte, ging er betrübt weg; denn er hatte viel Besitztum.',
        23: 'Jesus aber sprach zu Seinen Jüngern: Wahrlich, Ich sage euch: Es ist schwer, daß ein Reicher ins Reich der Himmel eingehe.',
        24: 'Wiederum aber sage Ich euch: Es ist leichter, daß ein Kamel durch ein Nadelöhr durchgehe, denn daß ein Reicher ins Reich Gottes eingehe.',
        25: 'Da aber die Jünger das hörten, staunten sie sehr und sagten: Wer kann dann gerettet werden?',
        26: 'Jesus aber blickte sie an und sprach zu ihnen: Bei Menschen ist dies unmöglich, bei Gott aber sind alle Dinge möglich.',
        27: 'Da antwortete Petrus und sprach zu Ihm: Siehe, wir haben alles verlassen und sind dir nachgefolgt. Was wird uns wohl werden?',
        28: 'Jesus aber sprach zu ihnen: Wahrlich, Ich sage euch, daß ihr, die ihr Mir seid nachgefolgt in der Wiedergeburt, wenn des Menschen Sohn sitzen wird auf dem Throne Seiner Herrlichkeit, auch ihr sitzen werdet auf zwölf Thronen und richten die zwölf Stämme Israels.',
        29: 'Und jeder, der Häuser, oder Brüder, oder Schwestern, oder Vater, oder Mutter, oder Weib, oder Kinder, oder Felder verläßt um Meines Namens willen, der soll es hundertfältig empfangen und das ewige Leben ererben.',
        30: 'Aber viele, welche Erste sind, werden Letzte, und Letzte werden Erste sein.',
    },
    20: {
        1: 'Denn das Reich der Himmel ist gleich einem Menschen, einem Hausherrn, der mit dem Morgen ausging, Arbeiter in seinen Weinberg zu dingen.',
        2: 'Er ward aber mit den Arbeitern eins über einen Denar den Tag, und sandte sie aus in seinen Weinberg.',
        3: 'Und um die dritte Stunde ging er aus und sah andere müßig im Markte stehen,',
        4: 'Und derselbe sprach: Gehet auch ihr hin in den Weinberg, und was gerecht ist, will ich euch geben.',
        5: 'Sie aber gingen hin. Um die sechste und die neunte Stunde ging er wieder aus und tat gleich also.',
        6: 'Als er aber um die elfte Stunde ausging, fand er andere müßig stehen und sprach zu ihnen: Was steht ihr so den ganzen Tag mü-ßig?',
        7: 'Sie sagen zu ihm: Es hat uns niemand gedungen. Sagt er zu ihnen: Gehet auch ihr hin in den Weinberg, und was gerecht ist, sollt ihr empfangen.',
        8: 'Als es Abend geworden, spricht der Herr des Weinbergs zu seinem Schaffner: Rufe die Arbeiter und gib ihnen den Lohn, und fange bei den letzten an bis zu den ersten.',
        9: 'Als die von der elften Stunde kamen, empfingen sie jeder seinen Denar.',
        10: 'Da aber die ersten kamen, dachten sie, sie würden mehr empfangen; aber auch sie empfingen jeder seinen Denar.',
        11: 'Wie sie aber den empfingen, murrten sie wider den Hausherrn,',
        12: 'Und sagten: Die letzten da haben nur eine Stunde gearbeitet, und du hast sie uns gleich gemacht, die des Tages Bürde und Hitze getragen haben.',
        13: 'Er aber antwortete und sprach zu einem von ihnen: Gesell, ich bin dir nicht ungerecht, bist du nicht mit mir um einen Denar eins geworden?',
        14: 'Nimm das Deine und gehe hin; ich will aber diesem letzten geben wie auch dir.',
        15: 'Oder ist mir nicht erlaubt, mit dem Meinen zu tun, was ich will? Ist dein Auge arg, weil ich gut bin?',
        16: 'So werden die Letzten Erste, und die Ersten Letzte sein; denn viele sind berufen, aber wenige sind auserwählt.',
        17: 'Und Jesus zog hinauf nach Jerusalem, und nahm die zwölf Jünger besonders zu Sich auf dem Wege und sagt zu ihnen:',
        18: 'Siehe, wir ziehen nach Jerusalem hinauf, und des Menschen Sohn wird den Hohenpriestern und Schriftgelehrten überantwortet werden, und sie werden Ihn zum Tode verdammen.',
        19: 'Und sie werden Ihn den Heiden überantworten, zu verspotten und zu geißeln und zu kreuzigen; und am dritten Tage wird Er auferstehen.',
        20: 'Da kam die Mutter der Söhne des Zebedäus mit ihren Söhnen zu Ihm, fiel vor Ihm nieder und bat etwas von Ihm.',
        21: 'Er aber sprach zu ihr: Was willst du? Sie spricht zu Ihm: Sage, daß diese meine zwei Söhne sitzen in Deinem Reiche, der eine zu Deiner Rechten, der andere zu Deiner Linken.',
        22: 'Jesus aber antwortete und sprach: Ihr wisset nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den Ich trinken werde, oder getauft werden mit der Taufe, da Ich mit getauft werde? Sie sprechen zu Ihm: Wir können es.',
        23: 'Und Er spricht zu ihnen: Meinen Kelch sollt ihr trinken, und mit der Taufe, mit der Ich getauft werde, sollt ihr getauft werden; aber das Sitzen zu Meiner Rechten und zu Meiner Linken ist nicht Mein zu geben, außer denen, welchen es von Meinem Vater bereitet ist.',
        24: 'Und als die zehn das hörten, wurden sie unwillig über die zwei Brüder.',
        25: 'Jesus aber rief sie zu Sich und sprach: Ihr wisset, daß die Obersten der Völkerschaften herrschen über sie und die Großen Gewalt üben über sie.',
        26: 'So soll es nicht sein unter euch; sondern wer unter euch will groß werden, der soll euer Diener sein,',
        27: 'Und wer unter euch will der Erste sein, der sei euer Knecht.',
        28: 'Wie des Menschen Sohn nicht gekommen ist, Sich dienen zu lassen, sondern zu dienen und Sein Leben zur Lösung zu geben für viele.',
        29: 'Und als sie von Jericho auszogen, folgte Ihm viel Volk nach.',
        30: 'Und siehe, zwei Blinde saßen am Wege, und da sie hörten, daß Jesus vorübergehe, schrien sie und sprachen: Erbarme Dich unser, Herr, Du Sohn Davids.',
        31: 'Das Volk aber bedrohte sie, daß sie stilleschweigen sollten. Sie aber schrien umso mehr: Ach, Herr, Du Sohn Davids, erbarme Dich unser!',
        32: 'Und Jesus blieb stehen und rief ihnen und sprach: Was wollt ihr, daß Ich euch tun soll?',
        33: 'Sie sprachen zu Ihm: Herr, daß unsere Augen aufgetan werden.',
        34: 'Es jammerte aber Jesus, und Er berührte ihre Augen; und alsbald wurden ihre Augen sehend, und sie folgen Ihm nach.',
    },
    21: {
        1: 'Und als sie sich Jerusalem nahten und nach Bethphage an den Ölberg kamen, da sandte Jesus zwei Jünger aus,',
        2: 'Und sprach zu ihnen: Gehet hin in den Flecken, der euch gegenüber ist, und alsbald werdet ihr eine Eselin finden angebunden, und ein Füllen bei ihr. Löset sie und führet sie zu Mir.',
        3: 'Und wenn euch jemand etwas sagt, sollt ihr sagen: Der Herr bedarf ihrer; alsbald aber wird er sie senden.',
        4: 'Alles dies geschah, auf daß erfüllt würde, was durch den Propheten gesagt ist, der da spricht:',
        5: 'Saget der Tochter Zion: Siehe, dein König kommt zu dir sanftmütig und reitet auf einem Esel und auf einem Füllen, dem Sohn eines Lasttiers.',
        6: 'Die Jünger aber gingen hin und taten, wie ihnen Jesus verordnet.',
        7: 'Sie führten die Eselin und das Füllen herbei und legten ihre Kleider auf sie, und Er setzte Sich darauf.',
        8: 'Die meisten vom Volke aber streuten ihre Kleider auf den Weg; andere aber schnitten Zweige von den Bäumen und streuten sie auf den Weg.',
        9: 'Das Volk aber, das voranzog, und das nachfolgte, schrie und sprach: Hosianna dem Sohne Davids! Gesegnet sei, Der da kommt in dem Namen des Herrn! Hosianna in den Höhen!',
        10: 'Und als Er in Jerusalem einzog, ward die ganze Stadt bewegt und sagte: Wer ist Der?',
        11: 'Das Volk aber sagte: Das ist Jesus, der Prophet aus Nazareth in Galiläa.',
        12: 'Und Jesus ging hinein in das Heiligtum Gottes und trieb aus alle Verkäufer und Käufer im Heiligtum und stieß die Tische der Wechsler um und die Stühle derer, die Tauben verkauften.',
        13: 'Und spricht zu ihnen: Es ist geschrieben: Mein Haus soll ein Bethaus heißen; ihr aber machtet es zu einer Räuberhöhle!',
        14: 'Und es kamen zu Ihm Blinde und Lahme in das Heiligtum, und Er heilte sie.',
        15: 'Da aber die Hohenpriester und die Schriftgelehrten die Wunder sahen, die Er tat, und die Kinder im Heiligtum schreien und sagen: Hosianna dem Sohne Davids!, wurden sie unwillig.',
        16: 'Und sprachen zu Ihm: Hörst Du, was diese sagen? Jesus aber sprach zu ihnen: Ja, habt ihr nie gelesen: aus dem Munde der Unmündigen und Säuglinge hast Du Dir Lob zugerichtet?',
        17: 'Und Er verließ sie und ging hinaus aus der Stadt nach Bethanien und übernachtete allda.',
        18: 'Als Er aber am Morgen wieder in die Stadt ging, hungerte Ihn.',
        19: 'Und da Er einen Feigenbaum am Wege sah, ging Er auf denselben zu und fand nichts an ihm, denn allein Blätter, und spricht zu ihm: Nimmer werde Frucht aus dir in Ewigkeit! Und sogleich verdorrte der Feigenbaum.',
        20: 'Und da es die Jünger sahen, verwunderten sie sich und sprachen: Wie ist der Feigen- baum so bald verdorrt!',
        21: 'Jesus aber antwortete und sprach zu ihnen: Wahrlich, Ich sage euch: So ihr Glauben habt, und zweifelt nicht, so werdet ihr nicht nur solches mit dem Feigenbaum tun; sondern so ihr zu diesem Berge sprechet: Hebe dich auf und wirf dich ins Meer, so wird es geschehen.',
        22: 'Und alles, was ihr bitten werdet im Gebet, so ihr glaubet, werdet ihr es empfangen.',
        23: 'Und als Er in das Heiligtum kam, kamen zu Ihm, als Er lehrte, die Hohenpriester und die Ältesten des Volkes und sprachen: Aus was für Gewalt tust Du das? Und wer hat Dir diese Gewalt gegeben?',
        24: 'Jesus aber antwortete und sprach zu ihnen: Ich will euch auch ein Wort fragen; wenn ihr Mir es sagt, werde Ich euch auch sagen, aus welcher Gewalt Ich dies tue.',
        25: 'Die Taufe des Johannes, woher war sie? Vom Himmel oder von Menschen? Sie aber bedachten bei sich und sagten: Wenn wir sprechen: Vom Himmel, so wird Er zu uns sagen: Warum habt ihr ihm denn nicht geglaubt?',
        26: 'Sagen wir aber: Von Menschen, so fürchten wir das Volk; denn alle halten den Johannes für einen Propheten.',
        27: 'Und sie antworteten Jesus und sagten: Wir wissen es nicht. Da sprach auch Er zu ihnen: Dann sage Ich euch auch nicht, aus was für Gewalt Ich dies tue.',
        28: 'Was meint ihr aber? Ein Mensch hatte zwei Kinder, und er ging herzu zum ersten und sagte: Kind, geh heute hin und arbeite in meinem Weinberg.',
        29: 'Der antwortete aber und sprach: Ich will nicht. Danach reute es ihn aber, und er ging hin.',
        30: 'Und er kam herzu zum zweiten und sprach ebenso. Der aber antwortete und sprach: Ja,, Herr, und ging nicht hin.',
        31: 'Welcher von den zweien hat den Willen des Vaters getan? Sie sprachen zu Ihm: Der erste. Spricht Jesus zu ihnen: Wahrlich, Ich sage euch: Die Zöllner und Buhlerinnen kommen vor euch ins Reich Gottes.',
        32: 'Denn Johannes kam zu euch auf dem Wege der Gerechtigkeit, und ihr glaubtet ihm nicht; die Zöllner aber und die Buhlerinnen glaubten ihm; ihr aber sahet es und es reute euch nicht danach, so daß ihr ihm geglaubt hättet.',
        33: 'Höret ein anderes Gleichnis. Es war ein Mensch, ein Hausherr, der pflanzte einen Weinberg und umgab ihn mit einem Zaun, grub darin eine Kelter, und baute einen Turm, und gab ihn an Weingärtner aus und zog über Land.',
        34: 'Als aber die Jahreszeit der Früchte nahte, sandte er seine Knechte aus an die Weingärtner, um seine Früchte zu empfangen.',
        35: 'Die Weingärtner aber nahmen seine Knechte, stäupten den einen, den andern aber töteten sie, einen andern aber steinigten sie.',
        36: 'Wiederum sandte er andere Knechte ab, mehr denn der ersten waren. Und sie taten ihnen gleich also.',
        37: 'Danach sandte er seinen eigenen Sohn an sie und sagte: Vor meinen Sohn werden sie sich scheuen.',
        38: 'Als die Weingärtner aber den Sohn sahen, sprachen sie untereinander: Dies ist der Erbe, kommet, lasset uns ihn töten und sein Erbe für uns behalten.',
        39: 'Und sie nahmen ihn, warfen ihn zum Weinberg hinaus und töteten ihn.',
        40: 'Wenn nun der Herr des Weinberges kommt, was wird er diesen Weingärtnern tun?',
        41: 'Sie sprachen zu ihm: Er wird die Bösen böse verderben und den Weinberg an andere Weingärtner ausgeben, die ihm in ihren Jahreszeiten die Früchte übergeben.',
        42: 'Spricht Jesus zu ihnen: Habt ihr nie in den Schriften gelesen: Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein geworden? Vom Herrn ist das geworden und ist wunderbar vor unseren Augen?',
        43: 'Darum sage Ich euch: Das Reich Gottes wird von euch weggenommen und einer Völkerschaft gegeben werden, die seine Früchte bringt.',
        44: 'Und wer auf diesen Stein fällt, wird zerschellt werden, auf den er aber fällt, den wird er zerschmettern.',
        45: 'Und da die Hohenpriester und Pharisäer Seine Gleichnisse hörten, erkannten sie, daß Er von ihnen sprach;',
        46: 'Und da sie suchten, Ihn zu ergreifen, fürchteten sie sich vor dem Gedränge, da es Ihn für einen Propheten hielt.',
    },
    22: {
        1: 'Und Jesus antwortete und sprach wiederum in Gleichnissen zu ihnen und sagte:',
        2: 'Das Reich der Himmel ist gleich einem Menschen, einem Könige, der seinem Sohne Hochzeit machte.',
        3: 'Und er sandte seine Knechte aus, um zu rufen die zur Hochzeit Berufenen, und sie wollten nicht kommen.',
        4: 'Wiederum sandte er andere Knechte aus und sprach: Saget den Berufenen: Siehe, mein Mahl habe ich bereitet, meine Ochsen und das Mastvieh sind geschlachtet und alles bereit. Kommet zur Hochzeit.',
        5: 'Aber sie achteten nicht darauf und gingen hin, der eine auf sein eigenes Feld, der andere seinem Handel nach;',
        6: 'Die übrigen aber ergriffen seine Knechte, beschimpften und töteten sie.',
        7: 'Als der König aber das hörte, ward er zornig und schickte seine Heere aus, brachte die Mörder um und verbrannte ihre Stadt.',
        8: 'Dann spricht er zu seinen Knechten: Die Hochzeit ist zwar bereit, aber die Berufenen waren es nicht wert.',
        9: 'So gehet denn an die Kreuzwege der Straßen und rufet, wen ihr findet, zur Hochzeit.',
        10: 'Und jene Knechte gingen aus auf die Wege, versammelten alle, die sie fanden, Schlechte und Gute, und die Hochzeit war voll derer, die zu Tische lagen.',
        11: 'Als der König aber hineinkam, um anzusehen, die zu Tische lagen, sah er daselbst einen Menschen, der hatte keine hochzeitliche Kleidung angetan.',
        12: 'Und er spricht zu ihm: Geselle, wie bist du hier hereingekommen und hast keine hochzeitliche Kleidung? Er aber verstummte.',
        13: 'Da sprach der König zu den Dienern: Bindet ihm Füße und Hände, werfet ihn in die äußerste Finsternis hinaus; da wird sein Weinen und Zähneknirschen.',
        14: 'Denn viele sind berufen, aber wenige sind auserwählt.',
        15: 'Da gingen die Pharisäer hin und hielten Beratung, wie sie Ihn im Worte verstrickten.',
        16: 'Und sandten ihre Jünger aus mit den Herodianern zu Ihm, die sprachen: Lehrer, wir wissen, daß Du wahrhaftig bist und den Weg Gottes in Wahrheit lehrst und Dich um niemand kümmerst; denn Du siehst nicht auf das Angesicht der Menschen;',
        17: 'So sage uns denn, was dünkt Dich? Ist es erlaubt, daß man dem Kaiser die Steuer gebe, oder nicht?',
        18: 'Jesus aber erkannte ihre Bosheit und sprach: Was versucht ihr Mich, ihr Heuchler?',
        19: 'Zeigt Mir die Münze der Steuer. Sie aber brachten Ihm einen Denar.',
        20: 'Und Er spricht zu ihnen: Wessen Bild und Überschrift ist dies?',
        21: 'Sie sagten zu Ihm: Des Kaisers. Da spricht Er zu ihnen: So gebt denn dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist.',
        22: 'Und wie sie das hörten, verwunderten sie sich, verließen Ihn und gingen weg.',
        23: 'An demselben Tage kamen die Sadduzäer zu Ihm, die da sagen, es sei keine Auferstehung, und fragten Ihn:',
        24: 'Lehrer, Moses hat gesagt: Wenn einer stirbt und hat keine Kinder, so soll sein Bruder sein Weib zur Schwiegerehe nehmen und seinem Bruder Samen erwecken.',
        25: 'Es waren aber bei uns sieben Brüder; und der erste freite und starb, und da er keinen Samen hatte, ließ er sein Weib seinem Bruder.',
        26: 'Desgleichen auch der zweite, und der dritte, bis zum siebenten.',
        27: 'Zuletzt nach allen starb auch das Weib.',
        28: 'Bei der Auferstehung nun, wessen Weib unter den sieben wird sie sein? Denn alle haben sie gehabt.',
        29: 'Jesus aber antwortete und sprach zu ihnen: Ihr irret, da ihr nicht wisset die Schriften, noch die Kraft Gottes.',
        30: 'Denn bei der Auferstehung freien sie nicht, noch lassen sie sich freien, sondern sind wie die Engel Gottes im Himmel.',
        31: 'Wegen der Auferstehung der Toten aber, habt ihr nicht gelesen, was euch von Gott gesagt wird, Der da spricht:',
        32: 'Ich bin der Gott Abrahams, und der Gott Isaaks und der Gott Jakobs? Gott ist nicht ein Gott der Toten, sondern der Lebendigen.',
        33: 'Und als das Volk dies hörte, staunte es über Seine Lehre.',
        34: 'Als aber die Pharisäer hörten, wie Er die Sadduzäer zum Verstummen gebracht hatte, versammelten sie sich.',
        35: 'Und einer von ihnen, ein Gesetzlehrer, fragte Ihn, um Ihn zu versuchen, und sprach:',
        36: 'Lehrer, welches ist das große Gebot im Gesetz?',
        37: 'Jesus aber sprach zu ihm: Du sollst den Herrn deinen Gott lieben mit deinem ganzen Herzen und mit deiner ganzen Seele und mit deinem ganzen Gemüte.',
        38: 'Dies ist das erste und große Gebot.',
        39: 'Das zweite aber ist ihm ähnlich: Du sollst deinen Nächsten lieben, wie dich selbst.',
        40: 'An diesen zwei Geboten hängt das ganze Gesetz und die Propheten.',
        41: 'Als aber die Pharisäer versammelt waren, fragte sie Jesus,',
        42: 'Und sagte: Was dünkt euch von Christus? Wessen Sohn ist Er?',
        43: 'Sie sagten zu Ihm: Davids. Spricht Er zu ihnen: Wie heißt ihn dann David im Geiste Herr, wenn er sagt:',
        44: 'Der Herr sprach zu meinem Herrn: Setze Dich zu Meiner Rechten, bis daß Ich Deine Feinde zum Schemel Deiner Füße lege.',
        45: 'Wenn nun David Ihn Herr heißt, wie ist Er sein Sohn?',
        46: 'Und niemand konnte Ihm ein Wort antworten; auch wagte von dem Tage an niemand mehr, Ihn zu fragen.',
    },
    23: {
        1: 'Da redete Jesus zu dem Volk und zu Seinen Jüngern,',
        2: 'Und sagte: Auf Moses Stuhl sitzen die Schriftgelehrten und die Pharisäer.',
        3: 'Alles nun, was sie euch sagen, daß ihr halten sollet, das haltet und tut; nach ihren Werken aber tut nicht; denn sie sagen es, tun es aber nicht.',
        4: 'Sie binden schwere und kaum erträgliche Lasten und legen sie auf der Menschen Schultern; sie aber wollen sie mit keinem Finger regen.',
        5: 'Alle ihre Werke aber tun sie, um von den Leuten angesehen zu werden. Sie machen ihre Denkzettel breit und vergrößern die Säume an ihren Kleidern.',
        6: 'Sie haben gern den ersten Platz bei Gastmählern, und die ersten Sitze in den Synagogen,',
        7: 'Und die Begrüßungen auf den Märkten, und daß die Menschen sie Rabbi, Rabbi hei-ßen.',
        8: 'Aber ihr sollt euch nicht Rabbi nennen lassen; denn Einer ist euer Lehrmeister, Christus; ihr alle aber seid Brüder.',
        9: 'Und ihr sollt niemand auf Erden euren Vater heißen; denn Einer ist euer Vater, Der in den Himmeln.',
        10: 'Auch Lehrmeister sollt ihr euch nicht heißen lassen; denn Einer ist euer Lehrmeister, Christus.',
        11: 'Aber der Größte unter euch soll euer Deiner sein.',
        12: 'Wer sich aber selbst erhöht, der wird erniedrigt, und wer sich selbst erniedrigt, der wird erhöht werden.',
        13: 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Ihr verschließet das Reich der Himmel vor den Menschen; denn ihr kommt nicht hinein; und die hineingehen möchten, lasset ihr nicht hineingehen.',
        14: 'Wehe aber euch Schriftgelehrte und Pharisäer, ihr Heuchler; denn ihr esset der Witwen Häuser auf und machet zum Vorwand lange Gebete, dafür werdet ihr ein noch schwerer Gericht empfangen.',
        15: 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler; denn ihr durchziehet das Meer und das Trockene, um einen einzigen Proselyten zu machen; und wenn er es geworden ist, macht ihr ihn zu einem Sohn der Hölle, doppelt mehr, als ihr selbst.',
        16: 'Wehe euch, blinde Wegweiser, die ihr sprecht: Wer beim Tempel schwört, das ist nichts; wer aber beim Golde des Tempels schwört, der schuldet es.',
        17: 'Ihr Narren und Blinde! Was ist den größer? das Gold oder der Tempel, der das Gold heiligt?',
        18: 'Und: Schwört einer beim Altar, so ist es nichts; schwört er aber bei der Gabe, die darauf ist, so schuldet er es.',
        19: 'Ihr Narren und Blinde! Was ist denn größer, die Gabe oder der Altar, der die Gabe heiligt?',
        20: 'Wer denn bei dem Altar schwört, schwört bei ihm und bei allem, was darauf ist.',
        21: 'Und wer beim Tempel schwört, der schwört bei ihm und Dem, Der darin wohnt.',
        22: 'Und wer bei dem Himmel schwört, der schwört bei dem Throne Gottes und bei Dem, Der darauf sitzt.',
        23: 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Ihr verzehntet Minze und Anis und Kümmel; das Schwerere des Gesetzes, das Gericht, und die Barmherzigkeit und den Glauben habt ihr verlassen. Dies sollte man tun und das andere nicht lassen.',
        24: 'Blinde Wegweiser, die ihr Mücken wegseihet, aber Kamele verschlinget.',
        25: 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Ihr reinigt das Äußere des Kelches und der Schüssel; inwendig aber sind sie voll Raubes und Unmäßigkeit.',
        26: 'Blinder Pharisäer, reinige zuerst das Innere des Kelches und der Schüssel, auf daß auch das Äußere derselben rein werde.',
        27: 'Wehe, euch Schriftgelehrte und Pharisäer, ihr Heuchler; denn ihr gleicht übertünchten Grabstätten, die auswendig schön erscheinen, inwendig aber voller Totengebeine und aller Unreinigkeit sind.',
        28: 'So erscheint auch ihr von außen den Menschen als gerecht, indes ihr inwendig erfüllt seid von Heuchelei und Unrecht.',
        29: 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Ihr baut die Grabstätten der Propheten und schmückt die Grüfte der Gerechten,',
        30: 'Und sprechet: Wären wir in den Tagen unserer Väter gewesen, so wären wir nicht mit ihnen Teilhaber am Blute der Propheten gewesen.',
        31: 'Damit bezeugt ihr selber, daß ihr Söhne der Mörder der Propheten seid.',
        32: 'Und ihr erfüllt das Maß eurer Väter.',
        33: 'Ihr Schlangen, ihr Geschlecht der Ottern, wie solltet ihr dem Gerichte der Hölle entfliehen?',
        34: 'Darum siehe, Ich sende aus an euch Propheten und Weise und Schriftgelehrte, und ihr werdet derer etliche töten und kreuzigen, und etliche davon in euren Synagogen geißeln und verfolgen von Stadt zu Stadt.',
        35: 'Auf daß über euch komme all das gerechte Blut, das vergossen ist auf Erden, vom Blute des gerechten Abel bis auf das Blut Zacharias, des Sohnes von Barachjas, den ihr zwischen dem Tempel und dem Altar gemordet habt.',
        36: 'Wahrlich, Ich sage euch, solches alles wird kommen über dies Geschlecht.',
        37: 'Jerusalem, Jerusalem, die du tötest die Propheten und steinigst, die zu dir gesandt werden! Wie oft habe Ich deine Kinder versammeln wollen, wie eine Henne ihre Küchlein unter die Flügel versammelt, und ihr habt nicht gewollt!',
        38: 'Siehe, euer Haus wird euch wüste gelassen.',
        39: 'Denn Ich sage euch: Ihr werdet Mich von jetzt an nicht mehr sehen, bis ihr sprechet: Gesegnet sei, der da kommt im Namen des Herrn!',
    },
    24: {
        1: 'Und Jesus ging hinaus und ging weg von dem Heiligtum, und Seine Jünger kamen herzu, um Ihm die Gebäude des Heiligtums zu zeigen.',
        2: 'Jesus aber sprach zu ihnen: Sehet ihr nicht alles dies? Wahrlich, Ich sage euch: Kein Stein wird hier auf dem Steine gelassen, der nicht niedergerissen würde.',
        3: 'Als Er Sich aber auf dem Ölberg niedergesetzt hatte, kamen die Jünger zu Ihm besonders und sprachen: Sage uns, wann dies sein wird, und was das Zeichen Deiner Ankunft und der Vollendung des Zeitlaufes sein wird.',
        4: 'Und Jesus antwortete und sprach zu ihnen: Sehet zu, daß euch niemand irreführe.',
        5: 'Denn viele werden kommen unter Meinem Namen und sagen: Ich bin Christus, und werden viele irreführen.',
        6: 'Ihr werdet aber von Kriegen und Kriegserüchten hören; sehet zu, daß euch nicht bange wird; denn das muß alles geschehen; aber noch ist das Ende nicht da.',
        7: 'Denn es wird erweckt werden Völkerschaft wider Völkerschaft, und Königreich wider Königreich. Und es wird an verschiedenen Orten Hungersnot und Pestilenz und Erdbeben sein.',
        8: 'Alles dies aber ist nur der Anfang der Wehen.',
        9: 'Alsdann werden sie euch in Trübsal überantworten, und euch töten; und ihr werdet von allen Völkerschaften gehaßt werden um Meines Namens willen.',
        10: 'Und viele werden Ärgernis nehmen und einander überantworten und einander hassen.',
        11: 'Und viele falsche Propheten werden erweckt werden und viele irreführen.',
        12: 'Und weil das Unrecht sich mehrt, wird die Liebe vieler erkalten.',
        13: 'Wer aber beharrt bis ans Ende, der wird errettet werden.',
        14: 'Und dieses Evangelium vom Reiche wird im ganzen Erdkreis gepredigt werden zum Zeugnis über alle Völkerschaften, und dann wird das Ende kommen.',
        15: 'Wenn ihr nun sehen werdet den Greuel der Verwüstung, von dem durch den Propheten Daniel gesagt ist, am heiligen Orte stehen wer es liest, der merke auf;',
        16: 'Dann sollen die, so in Judäa sind, fliehen auf die Berge.',
        17: 'Wer auf dem Dache ist, steige nicht hinab, etwas aus seinem Hause zu nehmen.',
        18: 'Und wer auf dem Felde ist, kehre nicht um hinter sich, seine Kleider zu nehmen.',
        19: 'Wehe aber den Schwangeren und den Säugenden in jenen Tagen.',
        20: 'Betet aber, daß eure Flucht nicht im Winter oder am Sabbath geschehe.',
        21: 'Denn dann wird große Trübsal sein, wie sie seit Anfang der Welt bis jetzt nicht war, und auch nicht werden wird.',
        22: 'Und würden diese Tage nicht verkürzt, so würde kein Fleisch gerettet werden; aber um der Auserwählten willen werden diese Tage verkürzt.',
        23: 'Wenn dann einer euch sagen wird: Siehe, hier ist Christus, oder da, so glaubt es nicht!',
        24: 'Denn es werden falsche Christi und falsche Propheten auftreten und große Zeichen und Wunder geben, so daß, wenn es möglich wäre, sie selbst die Auserwählten irreführen.',
        25: 'Siehe, Ich habe es euch vorhergesagt.',
        26: 'Wenn sie euch dann sagen: Siehe, in der Wüste ist Er! so geht nicht hinaus; siehe, in den Kammern ist Er, so glaubt es nicht.',
        27: 'Denn wie der Blitz ausgeht vom Aufgang und scheint bis zum Niedergang, so wird auch die Ankunft des Menschen Sohnes sein.',
        28: 'Denn wo das Aas ist, da sammeln sich die Adler.',
        29: 'Alsbald aber nach der Trübsal jener Tage wird die Sonne verfinstert werden, und der Mond seinen Schein nicht geben, und die Sterne werden vom Himmel fallen, und die Kräfte der Himmel werden erschüttert werden.',
        30: 'Und dann wird das Zeichen des Menschen Sohnes im Himmel erscheinen, und dann werden alle Stämme der Erde jammern und des Menschen Sohn kommen sehen auf den Wolken des Himmels mit Kraft und großer Herrlichkeit.',
        31: 'Und Er wird Seine Engel aussenden mit großer Posaunenstimme, und sie werden Seine Auserwählten zusammenversammeln aus den vier Winden von einem Ende der Himmel bis an das andere.',
        32: 'Vom Feigenbaum aber lernt das Gleichnis: Wenn sein Zweig schon saftig wird und die Blätter hervortreibt, erkennt ihr, daß der Sommer nahe ist.',
        33: 'So sollt auch ihr, wenn ihr alles dies seht, erkennen, daß es nahe vor der Tür ist.',
        34: 'Wahrlich, Ich sage euch, dies Geschlecht wird mitnichten vergehen, bis daß dies alles geschehe.',
        35: 'Himmel und Erde werden vergehen, aber Meine Worte werden nicht vergehen.',
        36: 'Von jenem Tag und der Stunde aber weiß niemand, auch die Engel in den Himmeln nicht, sondern allein Mein Vater.',
        37: 'Wie die Tage Noachs waren, so wird auch die Ankunft des Menschen Sohnes sein.',
        38: 'Denn wie sie waren in den Tagen vor der Sündflut: sie aßen und tranken, sie freiten und ließen freien bis zu dem Tage, da Noach in die Arche einging,',
        39: 'Und erkannten es nicht, bis die Sündflut kam und sie alle wegnahm: so wird auch die Ankunft des Menschen Sohnes sein.',
        40: 'Dann werden zwei auf dem Felde sein, der eine wird angenommen, der andere gelassen.',
        41: 'Zwei mahlen in der Mühle; die eine wird angenommen, die andere gelassen.',
        42: 'So wachet denn: weil ihr nicht wisset, zu welcher Stunde euer Herr kommt.',
        43: 'Das aber erkennet, daß, wenn der Hausherr wüßte, um welche Nachtwache der Dieb kommt, er wohl wachte und ihn nicht ins Haus einbrechen ließe.',
        44: 'Deshalb seid auch ihr bereit; denn des Menschen Sohn kommt zu einer Stunde, da ihr es nicht meinet.',
        45: 'Wer ist wohl der treue und kluge Knecht, den sein Herr über sein Gesinde setzte, um ihnen zur rechten Zeit die Nahrung zu geben?',
        46: 'Selig ist jener Knecht, den sein Herr, wenn er kommt, findet also tun.',
        47: 'Wahrlich, Ich sage euch: Er wird ihn über alle seine Habe setzen.',
        48: 'So aber jener böse Knecht spricht in seinem Herzen: Mein Herr verziehet zu kommen,',
        49: 'Und fängt an, seine Mitknechte zu schlagen, und zu essen und zu trinken mit den Trunkenen:',
        50: 'So wird der Herr jenes Knechtes kommen an einem Tage, an dem er es nicht erwartet, und zu einer Stunde, die er nicht erkennt.',
        51: 'Und wird ihn zerscheitern und ihm sein Teil mit den Heuchlern anweisen. Da wird sein Weinen und Zähneknirschen.',
    },
    25: {
        1: 'Dann ist das Reich der Himmel zehn Jungfrauen zu vergleichen, die ihre Lampen nahmen und ausgingen, dem Bräutigam entgegen.',
        2: 'Fünf derselben aber waren klug und fünf töricht.',
        3: 'Die töricht waren, nahmen ihre Lampen, aber sie nahmen kein Öl mit sich.',
        4: 'Die klugen aber nahmen Öl in ihren Gefäßen mit ihren Lampen.',
        5: 'Da aber der Bräutigam verzog, nickten alle ein und schlummerten.',
        6: 'Um Mitternacht aber ward ein Geschrei: Siehe, der Bräutigam kommt, zieht aus, ihm entgegen!',
        7: 'Da erwachten alle diese Jungfrauen und schmückten ihre Lampen.',
        8: 'Die törichten aber sprachen zu den klugen: Gebt uns von eurem Öl, denn unsre Lampen erlöschen.',
        9: 'Die klugen aber antworteten und sagten: Nicht doch! da möchte es uns und euch nicht genügen. Geht vielmehr zu denen, die es verkaufen, und kauft euch!',
        10: 'Während sie aber hingingen zu kaufen, kam der Bräutigam; und die bereit waren, gingen mit ihm zur Hochzeit ein und die Tür ward verschlossen.',
        11: 'Danach kamen auch die übrigen Jungfrauen und sagten: Herr, Herr! Tue uns auf!',
        12: 'Er aber antwortete und sprach: Wahrlich, ich sage euch, ich kenne euch nicht.',
        13: 'Wachet also, denn ihr wisset den Tag und die Stunde nicht, da des Menschen Sohn kommt.',
        14: 'So wie ein Mensch, der über Land zog, seine eigenen Knechte rief und ihnen seine Habe übergab;',
        15: 'Und dem einen gab er fünf Talente, einem aber zwei, einem aber ein Talent, jedem nach seinen eigenen Kräften, und zog alsbald über Land.',
        16: 'Der aber die fünf Talente empfangen hatte, ging hin und arbeitete damit und gewann fünf andere Talente.',
        17: 'Desgleichen auch der mit den zweien, und auch er gewann zwei andere.',
        18: 'Der aber das eine empfangen hatte, ging hin und grub in der Erde, und verbarg das Silber seines Herrn.',
        19: 'Nach langer Zeit aber kommt der Herr dieser Knechte und hält mit ihnen Rechnung ab.',
        20: 'Und es kam herzu, der die fünf Talente empfangen, und brachte fünf andere Talente dazu, und sprach: Herr, fünf Talente hast du mir übergeben; siehe, ich habe fünf andere Talente zu denselben gewonnen.',
        21: 'Sein Herr sprach zu ihm: Wohl, du guter und getreuer Knecht; du warst über weniges getreu, ich werde dich über vieles setzen; gehe ein zur Freude deines Herrn!',
        22: 'Da kam aber auch herzu, der die zwei Talente empfangen hatte, und sprach: Herr, zwei Talente hast du mir übergeben; siehe, zwei andere Talente habe ich zu denselben gewonnen.',
        23: 'Sprach zu ihm sein Herr: Wohl, du guter und getreuer Knecht; du warst über weniges getreu, ich werde dich über vieles setzen. Gehe ein zur Freude deines Herrn!',
        24: 'Da kam aber auch herzu, der das eine Talent empfangen hatte, und sprach: Herr, ich kannte dich, daß du ein harter Mensch bist, erntest, wo du nicht gesät, und sammelst, wo du nicht ausgestreut hast.',
        25: 'Und ich fürchtete mich, ging hin, und verbarg dein Talent in der Erde; siehe, da hast du das deine.',
        26: 'Sein Herr aber antwortete und sprach zu ihm: Du schlechter und träger Knecht! Wußtest du, daß ich ernte, wo ich nicht gesät, und sammle, wo ich nicht ausgestreut habe?',
        27: 'Du hättest denn sollen mein Silber bei den Wechslern einlegen; und bei meinem Kommen hätte ich das Meinige mit Zins zurückerhalten.',
        28: 'Nehmt denn von ihm das Talent und gebt es dem, der zehn Talente hat.',
        29: 'Denn jedem, der da hat, wird gegeben, und er wird Überfluß haben; von dem aber, der nicht hat, von dem wird auch genommen, was er hat.',
        30: 'Und den unnützen Knecht werfet hinaus in die äußerste Finsternis. Da wird sein Weinen und Zähneknirschen.',
        31: 'Wenn aber des Menschen Sohn in Seiner Herrlichkeit kommen wird, und alle die heiligen Engel mit Ihm, dann wird Er sitzen auf dem Thron Seiner Herrlichkeit.',
        32: 'Denn alle Völkerschaften werden vor Ihm versammelt werden, und Er wird sie voneinander ausscheiden, wie der Hirte die Schafe von den Böcken ausscheidet.',
        33: 'Und Er wird die Schafe zu Seiner Rechten, die Böcke aber zu Linken stellen.',
        34: 'Dann wird der König zu denen auf Seiner Rechten sprechen: Kommt her, ihr Gesegneten Meines Vaters! Ererbet das Reich, das euch bereitet ist von der Gründung der Welt an.',
        35: 'Denn Ich hungerte, und ihr gabt Mir zu essen. Ich dürstete, und ihr habt Mich getränkt. Ich war ein Fremdling, und ihr habt Mich aufgenommen.',
        36: 'Ich war nackt, und ihr habt Mich umkleidet, Ich war krank, und ihr besuchtet Mich. Ich bin im Gefängnis gewesen, und ihr seid zu Mir gekommen.',
        37: 'Dann werden Ihm die Gerechten antworten und sagen: Herr, wann sahen wir Dich hungrig und nährten Dich, oder durstig und tränkten Dich?',
        38: 'Wann sahen wir Dich einen Fremdling und nahmen Dich auf? oder nackt und umkleideten Dich?',
        39: 'Wann sahen wir Dich krank oder im Gefängnis und sind zu Dir gekommen?',
        40: 'Und der König wird ihnen antworten und sprechen: Wahrlich, Ich sage euch: Was ihr an einem der kleinsten dieser Meiner Brüder getan, das habt ihr Mir getan.',
        41: 'Dann wird Er zu denen auf der Linken sprechen: Geht hinweg von Mir, ihr Verfluchten, in das ewige Feuer, das bereitet ist dem Teufel und seinen Engeln.',
        42: 'Denn Ich war hungrig, und ihr gabt Mir nichts zu essen; Ich dürstete, und ihr tränktet Mich nicht;',
        43: 'Ich war ein Fremdling, und ihr habt Mich nicht aufgenommen, nackt, und ihr habt Mich nicht umkleidet; krank, und im Gefängnis, und ihr habt Mich nicht besucht.',
        44: 'Dann werden auch sie antworten und sagen: Herr, wann sahen wir Dich hungrig oder durstig, oder fremd, oder nackt, oder krank oder im Gefängnis, und haben Dich nicht bedient?',
        45: 'Da wird Er ihnen antworten und sprechen: Wahrlich, Ich sage euch, was ihr dieser Kleinsten einem nicht getan, das habt ihr auch Mir nicht getan.',
        46: 'Und sie werden hingehen zur ewigen Strafe; die Gerechten aber in das ewige Leben.',
    },
    26: {
        1: 'Und es geschah, da Jesus alle diese Worte vollendet hatte, sprach Er zu Seinen Jüngern:',
        2: 'Ihr wisset, daß nach zwei Tagen Pascha wird; und des Menschen Sohn wird überantwortet, daß Er gekreuzigt werde.',
        3: 'Da versammelten sich die Hohenpriester und die Schriftgelehrten und die Ältesten des Volkes in dem Hof des Hohenpriesters, genannt Kaiaphas.',
        4: 'Und berieten sich, wie sie Jesus mit Trug ergriffen und töteten.',
        5: 'Sie sprachen aber: Nicht am Fest, damit nicht ein Getümmel werde unter dem Volk.',
        6: 'Da Jesus aber in Bethanien, im Hause Simons des Aussätzigen war,',
        7: 'Kam zu Ihm ein Weib, das hatte eine Alabasterbüchse kostbarer Salbe und goß sie über Sein Haupt, da Er zu Tische lag.',
        8: 'Da das aber die Jünger sahen, wurden sie unwillig und sprachen: Wozu diese Verschwendung?',
        9: 'Denn man hätte die Salbe um vieles verkaufen und es den Armen geben können.',
        10: 'Da das Jesus erkannte, sprach Er zu ihnen: Was bietet ihr dem Weibe Ungelegenheiten? Denn ein gutes Werk hat sie an Mir gewirkt.',
        11: 'Denn die Armen habt ihr allezeit bei euch, Mich aber habt ihr nicht allezeit.',
        12: 'Daß sie diese Salbe auf Meinen Leib goß, das hat sie für Mein Begräbnis getan.',
        13: 'Wahrlich, Ich sage euch: Wo in der ganzen Welt dies Evangelium gepredigt wird, wird man auch reden von dem, was sie getan hat, zu ihrem Gedächtnis.',
        14: 'Da ging einer von den Zwölfen, genannt Judas Ischariot, hin zu den Hohenpriestern,',
        15: 'Und sprach: Was wollt ihr mir geben, daß ich Ihn euch überantworte? Sie aber bestimmten ihm dreißig Silberlinge.',
        16: 'Und von da an suchte er eine gute Gelegenheit, daß er Ihn verriete.',
        17: 'Aber am ersten des Ungesäuerten kamen die Jünger zu Jesus und sagten: Wo willst Du, daß wir Dir bereiten, das Paschalamm zu essen?',
        18: 'Er aber sprach: Geht hin in die Stadt zu einem und sagt ihm: der Lehrer sagt: Meine Zeit ist nahe; bei dir halte Ich das Pascha mit Meinen Jüngern.',
        19: 'Und die Jünger taten, wie ihnen Jesus verordnet hatte, und bereiteten das Pascha.',
        20: 'Als es aber Abend geworden, legte Er Sich mit den Zwölfen zu Tisch.',
        21: 'Und da sie aßen, sprach Er: Wahrlich, Ich sage euch: Einer von euch wird Mich verraten.',
        22: 'Und sie wurden sehr betrübt, fingen an, ein jeglicher von ihnen, zu Ihm zu sagen: Ich bin es doch nicht, Herr?',
        23: 'Er aber antwortete und sprach: Der mit Mir die Hand in die Schale eintaucht, der wird Mich verraten.',
        24: 'Des Menschen Sohn geht zwar dahin, wie es von Ihm geschrieben ist; aber wehe jenem Menschen, durch den des Menschen Sohn verraten wird. Es wäre solchem Menschen besser, er wäre nie geboren.',
        25: 'Judas aber, der Ihn verriet, antwortete und sprach: Ich bin es doch nicht, Rabbi? Er spricht zu ihm: Du hast es gesagt.',
        26: 'Da sie aber aßen, nahm Jesus das Brot, und segnete, brach es, und gab es den Jüngern und sprach: Nehmet, esset, das ist Mein Leib!',
        27: 'Und Er nahm den Kelch, dankte, und gab ihnen den und sprach: Trinket alle daraus.',
        28: 'Denn das ist Mein Blut, das des Neuen Bundes, das für viele vergossen wird zur Vergebung der Sünden.',
        29: 'Aber Ich sage euch, Ich werde von nun an von diesem Gewächse des Weinstocks mitnichten trinken, bis zu dem Tage, da Ich es neu mit euch trinken werde in Meines Vaters Reiche.',
        30: 'Und nach dem Lobgesang gingen sie hinaus an den Ölberg.',
        31: 'Dann spricht Jesus zu ihnen: Ihr werdet euch in dieser Nacht alle an Mir ärgern; denn es ist geschrieben: Ich werde den Hirten schlagen und die Schafe der Herde werden sich zerstreuen.',
        32: 'Wenn Ich aber auferweckt bin, werde Ich euch nach Galiläa vorangehen.',
        33: 'Petrus aber antwortete und sprach zu Ihm: Wenn sich auch alle an Dir ärgern, so will doch ich mich nimmermehr ärgern.',
        34: 'Jesus sprach zu ihm: Wahrlich, Ich sage dir, in dieser selben Nacht, ehe der Hahn kräht, wirst du Mich dreimal verleugnen.',
        35: 'Spricht zu Ihm Petrus: Und wenn ich auch mit Dir sterben müßte, werde ich Dich mitnichten verleugnen, desgleichen sprachen auch alle Jünger.',
        36: 'Da kommt Jesus mit ihnen an einen Hof, Gethsemane genannt, und spricht zu den Jüngern: Setzet euch hier, indes Ich dort hingehe und bete.',
        37: 'Und Er nahm mit Sich Petrus und die zwei Söhne des Zebedäus und fing an Sich zu betrüben und zu zagen.',
        38: 'Dann spricht Er zu ihnen: Meine Seele ist tief betrübt bis in den Tod. Bleibet hier und wachet mit Mir.',
        39: 'Und Er ging ein wenig vor, fiel auf Sein Angesicht, betete und sprach: Mein Vater, so es möglich ist, laß diesen Kelch an Mir vorübergehen, doch nicht, wie Ich will, sondern wie Du.',
        40: 'Und Er kommt zu den Jüngern und findet sie schlummernd, und spricht zu Petrus: So vermochtet ihr denn nicht eine Stunde mit Mir zu wachen?',
        41: 'Wachet und betet, auf daß ihr nicht in Versuchung kommt. Der Geist zwar ist willig, aber das Fleisch ist schwach,',
        42: 'Und Er ging wieder zum zweiten Male hin, betete und sprach: Mein Vater, kann dieser Kelch nicht an Mir vorübergehen, Ich trinke ihn denn, so geschehe Dein Wille!',
        43: 'Und Er kommt und findet sie abermals schlummernd; denn die Augen waren ihnen beschwert.',
        44: 'Und Er ließ sie und ging wieder hin und betete zum dritten Male, indem Er dieselben Worte sprach.',
        45: 'Da kommt Er zu Seinen Jüngern und spricht zu ihnen: So schlummert denn ferner und ruhet aus. Siehe, die Stunde ist nahe, und des Menschen Sohn wird in die Hände der Sünder überantwortet.',
        46: 'Macht euch auf, laßt uns gehen! Siehe, er ist nahe, der Mich verrät.',
        47: 'Und als Er noch redete, siehe, da kam Judas, einer der Zwölfe, und mit ihm vieles Gedränge mit Schwertern und Knitteln von den Hohenpriestern und Ältesten des Volkes.',
        48: 'Der Ihn verriet hatte ihnen aber ein Zeichen gegeben und gesagt: Der, Den ich küssen werde, Der ist es, Den ergreifet!',
        49: 'Und alsbald kam er zu Jesus herbei und sprach: Sei gegrüßt, Rabbi! und küßte Ihn.',
        50: 'Jesus aber sprach zu ihm: Weshalb bist du hier, Geselle? Da kamen sie herzu, legten die Hände an Jesus und ergriffen Ihn.',
        51: 'Und siehe, einer von denen, die bei Jesus waren, reckte die Hand aus, zog sein Schwert heraus und schlug des Hohenpriesters Knecht und hieb ihm das Ohr ab.',
        52: 'Da spricht Jesus zu ihm: Stecke dein Schwert an seinen Ort; denn alle, die das Schwert nehmen, sollen durch das Schwert umkommen.',
        53: 'Oder meinst du, Ich könnte nicht eben jetzt Meinen Vater anflehen, und Er würde Mir mehr den zwölf Legionen Engel zustellen?',
        54: 'Wie würden die Schriften dann erfüllt, daß es also geschehen muß?',
        55: 'Zur selben Stunde sprach Jesus zu dem Gedränge: Wie gegen einen Räuber seid ihr gegen Mich mit Schwertern und Knitteln ausgezogen, um Mich zu fangen. Täglich saß Ich bei euch und lehrte im Heiligtum, und ihr habt Mich nicht ergriffen.',
        56: 'Dies alles aber ist geschehen, daß die Schriften der Propheten erfüllt würden. Da verließen Ihn alle Seine Jünger und flohen.',
        57: 'Die aber Jesus ergriffen hatten, führten Ihn hin zum Hohenpriester Kaiaphas, wo sich die Schriftgelehrten und die Ältesten versammelt hatten.',
        58: 'Petrus aber folgte Ihm nach von weitem bis in den Hof des Hohenpriesters, ging hinein und setzte sich zu den Amtsdienern, um das Ende zu sehen.',
        59: 'Die Hohenpriester aber und die Ältesten und der ganze Rat suchten falsches Zeugnis wider Jesus, um Ihn zum Tode zu bringen;',
        60: 'Und sie fanden keines; und obgleich viele falsche Zeugen herzukamen, fanden sie keines. Danach kamen aber zwei falsche Zeugen herzu und sagten:',
        61: 'Dieser hat gesagt: Ich kann den Tempel Gottes niederreißen und in drei Tagen ihn aufbauen.',
        62: 'Und der Hohepriester stand auf und sprach zu Ihm: Antwortest Du nichts auf das, was diese wider Dich zeugen?',
        63: 'Jesus aber schwieg stille. Und der Hohepriester antwortete und sprach zu Ihm: Ich beschwöre Dich bei Gott dem Lebendigen, daß Du uns sagst, ob Du Christus, der Sohn Gottes bist?',
        64: 'Spricht zu ihm Jesus: Du hast es gesagt. Doch sage Ich euch: Hinfort werdet ihr des Menschen Sohn sitzen sehen zur Rechten der Kraft und kommen auf den Wolken des Himmels.',
        65: 'Da zerriß der Hohepriester seine Kleider und sprach: Er hat gelästert. Was bedürfen wir noch Zeugen? Seht, nun habt ihr Seine Lästerung gehört!',
        66: 'Was dünkt euch? Sie aber antworteten und sprachen: Er ist des Todes schuldig.',
        67: 'Da speieten sie Ihm ins Angesicht und schlugen Ihn mit Fäusten. Etliche aber gaben Ihm Backenstreiche,',
        68: 'Und sprachen: Weissage uns, Christus! Wer hat dich geschlagen?',
        69: 'Petrus aber saß draußen in dem Hof; und eine Magd kam zu ihm und sprach: Auch du warst mit Jesus, dem Galiläer.',
        70: 'Er aber leugnete vor allen und sprach: Ich weiß nicht, was du sagst.',
        71: 'Als er aber in das Tor hinauskam, sah ihn eine andere und sagte zu denen, die daselbst waren: Auch der da war mit Jesus, dem Nazarener.',
        72: 'Und er leugnete wiederum mit einem Schwur: Ich kenne den Menschen nicht.',
        73: 'Ein wenig danach aber kamen die dort Stehenden herzu und sprachen zu Petrus: Wahrlich, auch du bist einer von ihnen, denn auch deine Sprache macht dich kennbar.',
        74: 'Da fing er an, sich zu verwünschen und zu schwören: Ich kenne den Menschen nicht. Und alsbald krähte der Hahn.',
        75: 'Und Petrus gedachte der Rede Jesu, da Er zu ihm sprach: Ehe der Hahn kräht, wirst du Mich dreimal verleugnen. Und er ging hinaus und weinte bitterlich.',
    },
    27: {
        1: 'Als es aber Morgen ward, hielten alle Hohenpriester und die Ältesten des Volkes eine Beratung über Jesus, daß sie Ihn zum Tode brächten.',
        2: 'Und sie banden Ihn, führten Ihn hin und überantworteten Ihn dem Landpfleger Pontius Pilatus.',
        3: 'Da Judas, der Ihn verriet, sah, daß Er verurteilt war, reute es ihn, und er brachte die dreißig Silberlinge zurück den Hohenpriestern und den Ältesten,',
        4: 'Und sprach: Ich habe gesündigt, daß ich unschuldig Blut verraten. Sie aber sagten: Was geht das uns an? Sieh du zu.',
        5: 'Und er warf die Silberlinge dahin in den Tempel, entwich, ging hin und erhängte sich.',
        6: 'Die Hohenpriester aber nahmen die Silberlinge und sprachen: Es ist nicht erlaubt, sie in den Opferkasten zu werfen, weil es Schatzung des Blutes ist.',
        7: 'Sie hielten aber eine Beratung und kauften damit den Töpferacker zu einem Begräbnis für Fremde.',
        8: 'Daher jenes Feld bis auf den heutigen Tag der Blutacker heißt.',
        9: 'Da wurde erfüllt, was durch den Propheten Jeremias gesprochen ist, der sagt: Und sie nahmen die dreißig Silberlinge, die Schatzung dessen, der schätzt wurde, den sie sich schätzen ließen von den Söhnen Israels.',
        10: 'Und gaben sie für den Töpferacker, wie mir der Herr verordnet hat.',
        11: 'Jesus aber stand vor dem Landpfleger, und der Landpfleger fragte Ihn und sprach: Bist Du der Juden König? Jesus aber sprach zu ihm: Du sagst es.',
        12: 'Und da Er verklagt ward von den Hohenpriestern und den Ältesten, antwortete Er nichts.',
        13: 'Da spricht Pilatus zu Ihm: Hörst Du nicht, was sie wider Dich zeugen?',
        14: 'Und Er antwortete ihm nicht auf eine Rede, also daß sich der Landpfleger ungemein verwunderte.',
        15: 'Der Landpfleger hatte aber die Gewohnheit, dem Gedränge auf das Fest einen Gefangenen loszugeben, welchen sie wollten.',
        16: 'Sie hatten aber gerade einen besonderen Gefangenen, genannt Barabbas.',
        17: 'Da sie nun versammelt waren, sprach Pilatus zu ihnen: Welchen wollt ihr, daß ich euch losgebe? Barabbas oder Jesus, Der da genannt wird Christus?',
        18: 'Denn er wußte, daß sie Ihn aus Neid überantwortet hatten.',
        19: 'Indem er aber auf dem Richtstuhle saß, sandte sein Weib zu ihm und sagte: Habe du nichts zu tun mit diesem Gerechten; denn ich habe heute viel erlitten im Traum wegen Seiner.',
        20: 'Die Hohenpriester aber und die Ältesten überredeten das Gedränge, daß sie um Barabbas bitten sollten, Jesum aber umbrächten.',
        21: 'Der Landpfleger aber antwortete und sprach zu ihnen: Welchen wollt ihr von den zweien, daß ich euch losgebe? Sie aber sprachen: Barabbas!',
        22: 'Spricht Pilatus zu ihnen: Was soll ich denn mit Jesus tun, Der Christus genannt wird? Sie sprachen alle: Er soll gekreuzigt werden!',
        23: 'Der Landpfleger aber sprach: Was hat Er denn Böses getan? Sie aber schrien viel mehr und sprachen: Er soll gekreuzigt werden!',
        24: 'Da Pilatus aber sah, daß es nicht nützte, sondern des Getümmels mehr ward, nahm er Wasser, wusch sich die Hände vor dem Gedränge und sprach: Ich bin unschuldig an dem Blute dieses Gerechten! Seht ihr zu.',
        25: 'Und das ganze Volk antwortete und sprach: Sein Blut sei auf uns und unseren Kindern!',
        26: 'Da gab er ihnen Barabbas los, Jesus aber ließ er geißeln und überantwortete Ihn, daß Er gekreuzigt würde.',
        27: 'Da nahmen die Kriegsknechte des Landpflegers Jesus in das Richthaus und versammelten die ganze Kohorte über Ihn.',
        28: 'Und sie zogen Ihn aus und legten Ihm einen Scharlachmantel um;',
        29: 'Und sie flochten einen Krone von Dornen und setzten sie Ihm auf Sein Haupt, und ein Rohr in Seine Rechte, fielen auf das Knie vor Ihm und verspotteten Ihn und sagten: Sei gegrüßt, König der Juden!',
        30: 'Und speieten Ihn an und nahmen das Rohr und schlugen Ihn auf Sein Haupt.',
        31: 'Und als sie Ihn verspottet hatten, zogen sie Ihm den Mantel aus, und taten Ihm Seine Kleider an und führten Ihn ab, daß sie Ihn kreuzigten.',
        32: 'Indem sie aber hinauszogen, fanden sie einen Menschen von Kyrene mit Namen Simon; den nötigten sie, Sein Kreuz zu tragen.',
        33: 'Und als sie an den Ort kamen, genannt Golgatha, das heißt Schädelstätte,',
        34: 'Gaben sie Ihm Essig, mit Galle vermischt, zu trinken, und als Er es kostete, wollte Er nicht trinken.',
        35: 'Als sie Ihn aber gekreuzigt hatten, verteilten sie Seine Kleider unter sich, indem sie das Los warfen; auf daß erfüllt würde, was durch den Propheten gesagt ist: Sie verteilten Meine Kleider unter sich, und warfen das Los über Meinen Rock.',
        36: 'Und sie saßen da und bewachten Ihn.',
        37: 'Und über Seinem Haupte setzten sie in einer Aufschrift die Ursache Seines Todes: Dies ist Jesus, der Juden König.',
        38: 'Alsdann wurden mit Ihm gekreuzigt zwei Räuber, einer zur Rechten, und einer zur Linken.',
        39: 'Die aber vorübergingen, lästerten Ihn, indem sie ihre Köpfe schüttelten.',
        40: 'Und sagten: Der Du den Tempel niederreißt und in drei Tagen aufbaust, rette Dich Selber! Wenn Du Gottes Sohn bist, so steige herab von dem Kreuz!',
        41: 'Desgleichen verspotteten Ihn auch die Hohenpriester mit den Schriftgelehrten und Ältesten und sprachen:',
        42: 'Andere hat Er gerettet, Sich Selbst kann Er nicht retten! Wenn Er Israels König ist, so steige Er nun herab vom Kreuz, und wir wollen Ihm glauben.',
        43: 'Er hat auf Gott vertraut! Der errette Ihn nun, wenn Er Ihn will. Denn Er hat gesagt: Ich bin Gottes Sohn!',
        44: 'Ebenso aber schmähten Ihn auch die Räuber, die mit Ihm gekreuzigt waren.',
        45: 'Aber von der sechsten Stunde an ward Finsternis über das ganze Land bis zur neunten Stunde.',
        46: 'Um die neunte Stunde aber schrie Jesus auf mit großer Stimme und sprach: Eli, Eli lama sabachthani, das ist: Mein Gott, Mein Gott, warum hat Du Mich verlassen?',
        47: 'Einige aber der dort Stehenden, da sie es hörten, sagten: Er ruft den Elias herbei.',
        48: 'Und alsbald lief einer von ihnen und nahm einen Schwamm, füllte ihn mit Essig, legte ihn um ein Rohr und tränkte Ihn.',
        49: 'Die übrigen aber sagten: Halt, laß sehen, ob Elias kommt, Ihn zu retten.',
        50: 'Jesus aber schrie abermals mit großer Stimme und gab den Geist auf.',
        51: 'Und siehe, der Vorhang des Tempels zerriß entzwei von oben bis unten, und die Erde bebte und die Felsen zerrissen.',
        52: 'Und die Grüfte taten sich auf und viele Leiber der entschlafenen Heiligen wurden auferweckt.',
        53: 'Und gingen aus von den Grüften und kamen nach Seiner Auferstehung herein in die heilige Stadt und erschienen vielen.',
        54: 'Da aber der Hauptmann und die mit ihm Jesus bewachten sahen das Erdbeben und das, was geschah, fürchteten sie sich sehr und sprachen: Fürwahr, Dieser war Gottes Sohn!',
        55: 'Es waren aber da viele Frauen, die von weitem zuschauten; die Jesus aus Galiläa nachgefolgt waren, um Ihm Dienste zu tun.',
        56: 'Und unter ihnen waren Maria von Magdala, und Maria, des Jakobus und des Joses Mutter und die Mutter der Söhne des Zebedäus.',
        57: 'Als es aber Abend ward, kam ein reicher Mensch von Arimathäa, mit Namen Joseph, der auch ein Jünger Jesu war.',
        58: 'Dieser ging herbei zu Pilatus und bat um den Leib Jesu. Da befahl Pilatus, daß der Leib ihm sollte übergeben werden.',
        59: 'Und Joseph nahm den Leib, wickelte ihn ein in reine Leinwand,',
        60: 'Und legte ihn in seine neue Gruft, die er hatte in den Fels hauen lassen, und wälzte einen großen Stein vor die Tür zu der Gruft und ging weg.',
        61: 'Es war aber dort Maria von Magdala und die andere Maria, die saßen der Grabstätte gegenüber.',
        62: 'Am folgenden Tag aber, der nach dem Rüsttag ist, versammelten sich die Hohenpriester und die Pharisäer zu Pilatus,',
        63: 'Und sagten: Herr, wir erinnern uns, daß dieser Verführer, da Er noch lebte, gesagt hat: Nach drei Tagen werde Ich auferweckt.',
        64: 'So befiehl denn, daß man sich der Grabstätte bis zum dritten Tag versichere, auf daß nicht Seine Jünger kommen, Ihn stehlen und dem Volke sagen: Er ist von den Toten auferweckt! und die letzte Verführung schlimmer werde als die erste.',
        65: 'Pilatus sprach zu ihnen: Ihr sollt eine Wache haben, geht hin und versichert euch, wie ihr es wisset.',
        66: 'Sie aber gingen hin, versicherten sich der Grabstätte und mit der Wache versiegelten sie den Stein.',
    },
    28: {
        1: 'Spät aber am Sabbath, als schon der erste Wochentag dämmern wollte, kam Maria von Magdala und die andere Maria, die Grabstätte zu beschauen.',
        2: 'Und siehe, das geschah ein großes Erdbeben; denn der Engel des Herrn stieg vom Himmel herab, kam hinzu, wälzte den Stein weg von der Tür und setzte sich darauf.',
        3: 'Er war aber anzusehen wie ein Blitz und sein Kleid weiß wie Schnee.',
        4: 'Aber aus Furcht vor ihm erbebten, die es bewachten, und wurden wie tot.',
        5: 'Der Engel aber hob an und sprach zu den Weibern: Fürchtet euch nicht; denn ich weiß, daß ihr Jesus den Gekreuzigten sucht.',
        6: 'Er ist nicht hier; denn Er ist auferweckt, wie Er gesagt hat. Kommt her, und seht den Ort, da der Herr gelegen hat.',
        7: 'Und geht schnell hin und sagt Seinen Jüngern, daß Er von den Toten auferweckt ist. Und siehe, Er geht vor euch hin nach Galiläa. Dort werdet ihr Ihn sehen. Siehe, ich habe es euch gesagt.',
        8: 'Und sie gingen schnell hinaus von der Gruft mit Furcht und großer Freude und liefen, es Seinen Jüngern anzusagen.',
        9: 'Wie sie aber hingingen, es Seinen Jüngern anzusagen, begegnete ihnen Jesus und sprach: Seid gegrüßt! Sie aber kamen herzu, ergriffen Seine Füße und beteten Ihn an.',
        10: 'Da spricht Jesus zu ihnen: Fürchtet euch nicht! Geht hin und sagt Meinen Brüdern an, daß sie nach Galiläa hingehen, und dort werden sie Mich sehen.',
        11: 'Während sie aber hingingen, siehe, da kamen einige von der Wache in die Stadt und sagten den Hohenpriestern an alles, was geschehen war.',
        12: 'Und sie versammelten sich mit den Ältesten und faßten einen Beschluß und gaben den Kriegsknechten Silbers genug,',
        13: 'Und sprachen: Sagt, Seine Jünger sind in der Nacht gekommen und haben Ihn gestohlen, während wir schliefen.',
        14: 'Und wenn der Landpfleger davon hört, wollen wir ihn überreden, und euch außer Sorge setzen.',
        15: 'Sie aber nahmen die Silberlinge und taten, wie sie gelehrt waren. Und solches Wort ist bei den Juden ruchbar bis auf den heutigen Tag.',
        16: 'Die elf Jünger aber gingen hin nach Galiläa auf den Berg, wohin sie Jesus beschieden hatte.',
        17: 'Und da sie Ihn sahen, fielen sie vor Ihm nieder; einige aber zweifelten.',
        18: 'Und Jesus kam zu ihnen, redete mit ihnen und sprach: Mir ist gegeben alle Gewalt im Himmel und auf Erden.',
        19: 'Darum gehet hin und macht zu Jüngern alle Völkerschaften und taufet sie im Namen des Vaters und des Sohnes und des Heiligen Geistes.',
        20: 'Und lehret sie halten alles, was Ich euch geboten habe. Und siehe, Ich bin mit euch alle Tage bis zur Vollendung des Zeitlaufs. Amen.',
    },
}
